/* Spanish translation of the CCST Networking practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("ccst-networking", {
  "cs1": ["Una solicitud de página web baja por la pila en una PC. ¿En qué capa del modelo TCP/IP se agregan los números de puerto TCP?", ["Aplicación", "Transporte", "Internet", "Acceso a la red"], "Los números de puerto TCP y UDP pertenecen a la capa de Transporte. La capa de Internet agrega direcciones IP, no puertos.", ["La capa de Aplicación crea la solicitud en sí (HTTP, DNS); no agrega números de puerto a un segmento.", null, "La capa de Internet agrega direcciones IP de origen y destino, no puertos TCP o UDP.", "La capa de Acceso a la red agrega direcciones MAC y convierte las tramas en señales; para entonces los puertos ya están en su lugar."]],
  "cs2": ["¿Qué dirección usa un switch para reenviar una trama dentro de la red local?", ["La dirección IP de destino", "El número de puerto de destino", "La dirección MAC de destino", "La dirección de la puerta de enlace predeterminada"], "Los switches reenvían tramas Ethernet por la dirección MAC de destino. Las direcciones IP las usan los routers para mover paquetes entre redes.", ["Los routers usan las direcciones IP de destino para mover paquetes entre redes; un switch de Capa 2 solo mira el encabezado MAC de la trama.", "Los números de puerto identifican aplicaciones en la capa de Transporte, y un switch básico no los lee para reenviar tramas.", null, "La dirección de la puerta de enlace predeterminada es lo que un host usa para alcanzar otras redes; un switch no reenvía tramas basándose en ella."]],
  "cs3": ["¿Cómo se llama la unidad de datos en la capa de enlace de datos?", ["Trama (frame)", "Segmento", "Paquete", "Bit"], "La Capa 2 encapsula los datos en tramas. Los paquetes son de Capa 3 y los segmentos de Capa 4.", [null, "Un segmento es la unidad de Capa 4 (transporte) que lleva los números de puerto TCP o UDP.", "Un paquete es la unidad de Capa 3 que lleva las direcciones IP, una capa por encima de las tramas.", "Los bits son la representación física de la Capa 1, no la unidad de la capa de enlace de datos."]],
  "cs4": ["Un cliente paga por un plan de internet de 1 Gbps, pero una prueba de velocidad por Wi-Fi muestra 380 Mbps. ¿Qué describe la cifra de 380 Mbps?", ["Ancho de banda (bandwidth)", "Latencia de ida y vuelta", "Jitter (fluctuación)", "Rendimiento real (throughput)"], "El throughput es la tasa de datos realmente alcanzada. El ancho de banda es la capacidad máxima de 1 Gbps del plan.", ["El ancho de banda es la capacidad máxima del enlace, que aquí es el 1 Gbps que paga el cliente.", "La latencia es un retardo medido en milisegundos, no una tasa de datos en Mbps.", "El jitter es la variación del retardo entre paquetes, medido en milisegundos, no una tasa de transferencia.", null]],
  "cs5": ["Un técnico quiere medir la tasa de datos real entre dos PC de la oficina sin usar internet. ¿Qué herramienta encaja mejor?", ["iperf", "Una prueba de velocidad web", "nslookup", "tracert"], "iperf envía tráfico de prueba entre un cliente y un servidor que tú controlas, así que mide la ruta local. Una prueba de velocidad web mide en cambio la ruta a un servidor de internet.", [null, "Una prueba de velocidad web mide la ruta a un servidor de internet, que es justo lo que el técnico quiere evitar.", "nslookup consulta el DNS para resolver nombres; no mide tasas de datos.", "tracert lista los saltos de router y sus retardos a lo largo de una ruta; no mide el throughput."]],
  "cs6": ["Un usuario en una videollamada dice que las voces llegan tarde pero claras. ¿Qué medición describe cuánto tarda un dato en viajar del emisor al receptor?", ["Ancho de banda", "Latencia", "Rendimiento real (throughput)", "Tamaño del paquete"], "La latencia es el retardo para que los datos crucen la red. El ancho de banda es capacidad y por sí solo no describe el retardo.", ["El ancho de banda es la capacidad del enlace; con mucho ancho de banda los datos aún pueden llegar con un retardo largo.", null, "El throughput es la tasa de datos realmente alcanzada, que describe cuánto pasa, no cuánto tarda.", "El tamaño del paquete afecta ligeramente la eficiencia, pero no es una medición del tiempo de viaje por la red."]],
  "cs7": ["Una universidad conecta las redes de su biblioteca, dormitorios y edificios de ciencias en un mismo campus. ¿Qué tipo de red es esta?", ["PAN", "WAN", "CAN", "MAN"], "Una red de área de campus (CAN) enlaza edificios en un mismo sitio. Una MAN cubre una ciudad, y una WAN abarca distancias mayores.", ["Una PAN cubre unos pocos metros alrededor de una persona, como los dispositivos Bluetooth, no un campus entero.", "Una WAN abarca distancias largas como ciudades o países, normalmente a través de un proveedor de servicios, no edificios de un mismo sitio.", null, "Una MAN cubre un área metropolitana como una ciudad, que es más grande que un solo campus."]],
  "cs8": ["Unos audífonos inalámbricos están emparejados con un teléfono usando Bluetooth. ¿Qué tipo de red es esta?", ["PAN", "WLAN", "LAN", "CAN"], "Una red de área personal (PAN) cubre unos pocos metros alrededor de una persona. Una WLAN es Wi-Fi que cubre un edificio o una casa.", [null, "Una WLAN es una red Wi-Fi que cubre una casa o un edificio, no un enlace Bluetooth de corto alcance.", "Una LAN conecta dispositivos en un edificio o casa, normalmente con Ethernet y switches, no un emparejamiento entre teléfono y audífonos.", "Una CAN enlaza varios edificios en un mismo campus, mucho más grande que un enlace Bluetooth personal."]],
  "cs9": ["Una empresa enlaza sus oficinas en tres países distintos a través de un proveedor de servicios. ¿Qué tipo de red es esta?", ["MAN", "LAN", "CAN", "WAN"], "Una red de área amplia (WAN) conecta sitios a largas distancias. Una MAN se limita a alrededor de una ciudad.", ["Una MAN cubre alrededor de una ciudad, no oficinas en tres países.", "Una LAN cubre un solo edificio o sitio, no enlaces entre países.", "Una CAN conecta edificios en un mismo campus, no sitios en distintos países.", null]],
  "cs10": ["Una pequeña empresa quiere correo y documentos sin administrar ningún servidor ni sistema operativo. ¿Qué modelo de nube encaja?", ["IaaS", "PaaS", "SaaS", "En las instalaciones (on-premises)"], "Con SaaS el proveedor ejecuta toda la aplicación. IaaS todavía requiere que el cliente administre los sistemas operativos.", ["IaaS proporciona servidores virtuales, así que la empresa aún tendría que instalar y administrar sistemas operativos.", "PaaS todavía requiere que el cliente construya y administre sus propias aplicaciones sobre la plataforma.", null, "On-premises significa que la empresa aloja y administra sus propios servidores, lo opuesto de lo que quiere."]],
  "cs11": ["Una empresa mantiene sus servidores de nómina en su propio centro de datos pero ejecuta su sitio web en un proveedor de nube pública. ¿Qué despliegue es este?", ["Nube híbrida", "Nube privada", "Solo nube pública", "Nube comunitaria"], "Combinar recursos on-premises o privados con la nube pública es un despliegue híbrido. Una nube privada por sí sola no incluiría al proveedor público.", [null, "Una nube privada es infraestructura dedicada a una sola organización; no incluiría al proveedor público que aloja el sitio web.", "Solo nube pública significaría que los servidores de nómina también están en la nube pública, pero permanecen en el centro de datos de la empresa.", "Una nube comunitaria la comparten varias organizaciones con necesidades comunes, lo que no describe esta configuración."]],
  "cs12": ["Un desarrollador renta máquinas virtuales e instala y parchea el sistema operativo en cada una. ¿Qué modelo de servicio se está usando?", ["SaaS", "IaaS", "PaaS", "FaaS"], "IaaS proporciona servidores virtuales, almacenamiento y red, y el cliente administra el SO. PaaS ocultaría el SO al desarrollador.", ["Con SaaS el proveedor ejecuta toda la aplicación, así que el cliente nunca instala ni parchea un SO.", null, "PaaS oculta el sistema operativo; el desarrollador despliega código y el proveedor parchea el SO.", "FaaS (serverless) ejecuta funciones individuales sin servidores ni SO que el cliente deba administrar."]],
  "cs13": ["¿Cuál afirmación sobre TCP es correcta?", ["Envía datos sin ningún acuse de recibo (acknowledgment)", "Es el protocolo del que depende DHCP para asignar direcciones IP", "No tiene forma de detectar datos perdidos", "Establece una conexión con un saludo de tres vías (three-way handshake)"], "TCP es orientado a conexión: SYN, SYN-ACK, ACK, y luego datos con acuse de recibo y retransmisión. DHCP usa UDP, no TCP.", ["TCP acusa recibo de los datos recibidos; enviar sin acuses de recibo describe a UDP.", "DHCP usa los puertos UDP 67 y 68, no TCP.", "TCP usa números de secuencia y acuses de recibo para detectar datos perdidos y retransmitirlos.", null]],
  "cs14": ["Un firewall debe permitir la navegación web segura. ¿Qué puerto debería estar abierto?", ["TCP 443", "TCP 8080", "UDP 69", "TCP 21"], "HTTPS usa TCP 443. TCP 8080 es un puerto alterno común para HTTP simple, sin cifrar.", [null, "TCP 8080 es un puerto alterno común para HTTP simple o proxies, no el puerto estándar para la navegación segura.", "UDP 69 es TFTP, un protocolo simple de transferencia de archivos sin uso web.", "TCP 21 es el canal de control de FTP, no HTTPS."]],
  "cs15": ["Las PC de una red no están sincronizando su hora desde el servidor de tiempo. ¿Qué protocolo y puerto deberían revisarse?", ["SNMP en UDP 161", "DNS en UDP 53", "NTP en UDP 123", "TFTP en UDP 69"], "El Network Time Protocol usa UDP 123. DNS en el 53 resuelve nombres y no ajusta relojes.", ["SNMP en UDP 161 se usa para monitorear y administrar dispositivos, no para sincronizar relojes.", "DNS en UDP 53 resuelve nombres a direcciones IP y no ajusta la hora.", null, "TFTP en UDP 69 transfiere archivos como configuraciones e imágenes, no datos de tiempo."]],
  "cs16": ["Un técnico necesita copiar la configuración de un switch a un servidor sencillo que no tiene inicio de sesión ni autenticación. ¿Qué protocolo se usa comúnmente?", ["SFTP", "HTTPS", "SSH", "TFTP"], "TFTP (UDP 69) es un protocolo de transferencia simple sin autenticación, usado a menudo para configuraciones e imágenes de dispositivos. SFTP requiere un inicio de sesión.", ["SFTP se ejecuta sobre SSH y requiere un inicio de sesión, así que no encaja con un servidor sin autenticación.", "HTTPS es para tráfico web cifrado y normalmente requiere un servidor web con algún inicio de sesión para las subidas.", "SSH es un protocolo cifrado de inicio de sesión remoto que requiere autenticación.", null]],
  "cs17": ["¿Qué protocolo usa el comando ping?", ["ICMP", "UDP", "ARP", "DHCP"], "Ping envía solicitudes de eco ICMP y espera respuestas de eco. ARP resuelve direcciones IP a direcciones MAC y no es lo que usa ping.", [null, "UDP es un protocolo de transporte con puertos; ping trabaja en la capa de Internet con mensajes de eco ICMP, no UDP.", "ARP mapea direcciones IP a direcciones MAC en el enlace local; puede ejecutarse antes de un ping pero no es lo que ping envía.", "DHCP asigna direcciones IP a los hosts y no tiene nada que ver con probar la accesibilidad."]],
  "cs18": ["¿Qué par de protocolos normalmente usa UDP en lugar de TCP?", ["HTTP y HTTPS", "Consultas DNS y DHCP", "SSH y FTP", "SMTP y HTTPS"], "Las consultas DNS estándar (UDP 53) y DHCP (UDP 67/68) usan UDP. SSH y FTP usan TCP.", ["HTTP y HTTPS normalmente se ejecutan sobre TCP (80 y 443) porque las páginas web necesitan entrega confiable.", null, "SSH (22) y FTP (20/21) usan ambos TCP para sesiones confiables.", "SMTP (25) y HTTPS (443) usan ambos TCP."]],
  "cs19": ["¿Cuál de estas direcciones es una dirección IPv4 privada?", ["172.32.4.10", "192.169.1.5", "11.0.0.8", "172.20.15.3"], "El rango privado 172.16.0.0/12 cubre 172.16.0.0 a 172.31.255.255, así que 172.20.15.3 es privada. 172.32.4.10 queda justo fuera de ese rango.", ["172.32.4.10 está justo pasando el final de 172.16.0.0/12, que termina en 172.31.255.255, así que es pública.", "192.169.1.5 está fuera de 192.168.0.0/16; solo 192.168.x.x es privada.", "11.0.0.8 está fuera del rango privado 10.0.0.0/8, así que es una dirección pública.", null]],
  "cs20": ["Veinte dispositivos en un hogar alcanzan internet a través de una sola dirección IPv4 pública. ¿Qué lo hace posible?", ["PAT (NAT overload)", "DNS", "Retransmisión DHCP (IP helper)", "Etiquetado de VLAN (VLAN tagging)"], "La traducción de direcciones de puerto (PAT) mapea muchas direcciones privadas a una sola dirección pública usando distintos números de puerto. DHCP entrega direcciones pero no las traduce.", [null, "DNS traduce nombres a direcciones IP; no permite que muchos dispositivos compartan una dirección pública.", "La retransmisión DHCP reenvía las solicitudes DHCP a un servidor en otra subred; no traduce direcciones.", "El etiquetado de VLAN separa el tráfico en LAN virtuales en un switch y no tiene nada que ver con compartir una IP pública."]],
  "cs21": ["Una laptop muestra la dirección 169.254.40.12 y no puede alcanzar nada. ¿Cuál es la causa más probable?", ["El servidor DNS está caído", "La laptop tiene una dirección IP duplicada", "La laptop no recibió respuesta de un servidor DHCP", "La puerta de enlace predeterminada está configurada con la dirección incorrecta"], "169.254.x.x es una dirección APIPA que un dispositivo se asigna a sí mismo cuando DHCP falla. Un problema de DNS no cambiaría la dirección IP.", ["Una caída de DNS rompe la resolución de nombres pero no hace que la laptop se asigne una dirección 169.254.x.x.", "Una dirección IP duplicada causa conflictos, pero una dirección asignada por DHCP seguiría estando en el rango normal, no en APIPA.", null, "Una puerta de enlace incorrecta detiene el tráfico hacia otras redes, pero la laptop todavía tendría su dirección DHCP normal."]],
  "cs22": ["¿Qué máscara de subred corresponde al prefijo /26?", ["255.255.255.0", "255.255.255.192", "255.255.255.128", "255.255.255.224"], "/26 son 24 bits más 2 adicionales: 128 + 64 = 192. 255.255.255.224 es /27.", ["255.255.255.0 es /24, dos bits más corta que /26.", null, "255.255.255.128 es /25, un bit más corta que /26.", "255.255.255.224 es /27, un bit más larga que /26."]],
  "cs23": ["¿Cuántas direcciones de host utilizables hay en una subred /27?", ["30", "32", "62", "14"], "/27 deja 5 bits de host: 2^5 = 32, menos las direcciones de red y de broadcast = 30. 32 es el total, no el conteo de utilizables.", [null, "32 es el número total de direcciones en una /27, incluidas las direcciones de red y de broadcast, que no pueden asignarse.", "62 hosts utilizables corresponde a una /26, que tiene 6 bits de host.", "14 hosts utilizables corresponde a una /28, que tiene 4 bits de host."]],
  "cs24": ["Un host es 10.1.1.70/26. ¿Cuál es su dirección de red?", ["10.1.1.0", "10.1.1.32", "10.1.1.64", "10.1.1.70"], "/26 usa bloques de 64 (0, 64, 128, 192). 70 cae en 64 a 127, así que la red es 10.1.1.64.", ["10.1.1.0 es la red para los hosts .0 a .63; .70 está en el siguiente bloque /26.", "Los bloques de 32 corresponden a una /27; una /26 usa bloques de 64, así que .32 no es un límite de red /26.", null, "10.1.1.70 es la dirección propia del host, no la dirección de red, que tiene todos los bits de host en 0."]],
  "cs25": ["La PC A es 192.168.5.20/25 y la PC B es 192.168.5.140/25 sin un router entre ellas. ¿Por qué no pueden hacerse ping?", ["Están en subredes diferentes", "Comparten la misma dirección de broadcast", "Una /25 permite solo dos hosts", "Ambas direcciones son públicas"], "Una /25 divide la red en .128: .0 a .127 y .128 a .255, así que las PC están en subredes diferentes y necesitan un router. No comparten una dirección de broadcast.", [null, "No comparten una dirección de broadcast: la de la PC A es .127 y la de la PC B es .255, que es parte de por qué están en subredes diferentes.", "Una /25 tiene 7 bits de host y permite 126 hosts utilizables; dos hosts es una /30.", "Ambas direcciones están en 192.168.0.0/16, que es un rango privado."]],
  "cs26": ["¿Cuál es la dirección de broadcast de 192.168.8.0/24?", ["192.168.8.0", "192.168.8.1", "192.168.255.255", "192.168.8.255"], "La dirección de broadcast tiene todos los bits de host en 1, que es .255 en una /24. 192.168.8.0 es la dirección de red.", ["192.168.8.0 es la dirección de red, con todos los bits de host en 0.", "192.168.8.1 es la primera dirección de host utilizable, a menudo una puerta de enlace, no el broadcast.", "192.168.255.255 sería el broadcast de 192.168.0.0/16, no de una /24.", null]],
  "cs27": ["¿Cuál es una forma abreviada válida de 2001:0db8:0000:0000:0000:0000:0000:0010?", ["2001:db8::1", "2001:db8::10", "2001:db8:0:10", "2001::db8::10"], "Quita los ceros a la izquierda y reemplaza la secuencia de ceros con :: una sola vez, dando 2001:db8::10. El :: puede aparecer solo una vez, así que 2001::db8::10 es inválida.", ["2001:db8::1 termina en 1, pero el último hexteto original es 0010, que se abrevia a 10, no a 1.", null, "2001:db8:0:10 tiene solo cuatro hextetos y ningún ::, así que no representa la dirección completa de ocho hextetos.", "El atajo :: puede usarse solo una vez; dos de ellos hacen la dirección ambigua e inválida."]],
  "cs28": ["Una dirección IPv6 comienza con fe80. ¿Qué tipo de dirección es?", ["Unicast global", "Multicast", "Enlace-local (link-local)", "Loopback"], "fe80::/10 es enlace-local, usada solo en el enlace local. Las direcciones multicast comienzan con ff.", ["Las direcciones unicast globales están en 2000::/3 y suelen comenzar con 2 o 3, no con fe80.", "Las direcciones multicast comienzan con ff, no con fe80.", null, "La dirección de loopback de IPv6 es ::1, no una dirección que comience con fe80."]],
  "cs29": ["Una laptop construye su propia dirección global IPv6 a partir del prefijo anunciado por el router sin un servidor DHCP. ¿Cómo se llama esto?", ["SLAAC", "APIPA", "PAT", "DHCPv4"], "La autoconfiguración de direcciones sin estado (SLAAC) usa el prefijo de los anuncios del router. APIPA es un mecanismo de respaldo de IPv4, no de IPv6.", [null, "APIPA es el respaldo IPv4 169.254.x.x cuando DHCP falla; no usa prefijos anunciados por el router.", "PAT traduce muchas direcciones privadas a una sola dirección pública y no asigna direcciones a los hosts.", "DHCPv4 es un protocolo IPv4 basado en servidor, mientras que aquí la laptop construye una dirección IPv6 sin un servidor."]],
  "cs30": ["Un técnico debe tender un cable de red de 70 metros por el techo de una oficina y soportar 10 Gbps. ¿Qué cable es la mejor opción?", ["Cat 5e", "Cat 6a", "Cat 3", "Coaxial RG-6"], "Cat 6a soporta 10 Gbps hasta 100 m. Cat 5e está calificado para 1 Gbps.", ["Cat 5e está calificado para 1 Gbps; no está especificado para 10GBASE-T sobre 70 m.", null, "Cat 3 es un cable antiguo de grado de voz que soporta solo alrededor de 10 Mbps de Ethernet.", "El coaxial RG-6 se usa para TV por cable y módems de cable, no para tendidos Ethernet de 10 Gbps a dispositivos de oficina."]],
  "cs31": ["¿Qué conector se usa en un cable de parcheo Ethernet estándar?", ["RJ-11", "BNC", "F-type", "RJ-45"], "RJ-45 es el conector de 8 pines usado para Ethernet de par trenzado. RJ-11 es el conector telefónico más pequeño.", ["RJ-11 es el conector más pequeño de 6 posiciones usado para líneas telefónicas y DSL.", "BNC es un conector coaxial de bayoneta usado en Ethernet antiguo y equipo de video, no en cables de parcheo modernos.", "F-type es un conector coaxial roscado para TV por cable y módems de cable.", null]],
  "cs32": ["Dos edificios están a 5 km de distancia. ¿Qué cable debería conectarlos?", ["Fibra monomodo (single-mode)", "Fibra multimodo (multimode)", "Cable de cobre Cat 6 blindado", "Cable coaxial"], "La fibra monomodo transporta señales por muchos kilómetros. La multimodo se limita a tendidos mucho más cortos, y el Ethernet de cobre se detiene en 100 m.", [null, "La fibra multimodo está diseñada para tendidos más cortos, típicamente cientos de metros, no 5 km.", "El Ethernet de cobre, blindado o no, se limita a 100 m por tendido.", "El cable coaxial no se usa para enlaces Ethernet de esta longitud entre edificios y no alcanzaría 5 km a velocidades modernas."]],
  "cs33": ["Un módem de cable se conecta a la toma de pared del proveedor con un conector roscado que se atornilla. ¿Qué conector es?", ["LC", "RJ-45", "F-type", "ST"], "La TV por cable y el internet por cable usan coaxial con conectores F-type que se atornillan. LC y ST son conectores de fibra.", ["LC es un conector de fibra pequeño con enganche, no un conector coaxial roscado.", "RJ-45 es un conector Ethernet de par trenzado que se engancha, no un conector coaxial que se atornilla.", null, "ST es un conector de fibra redondo de bayoneta, no se usa para coaxial de TV por cable."]],
  "cs34": ["Un switch tiene una ranura vacía que acepta un módulo intercambiable en caliente (hot-swappable) para conectarse a fibra. ¿Cómo se llama este módulo?", ["Inyector PoE", "Transceptor SFP", "Panel de parcheo (patch panel)", "Keystone de medios"], "Los transceptores SFP (small form-factor pluggable) se insertan en las ranuras del switch para soportar fibra o cobre. Un panel de parcheo es un punto de terminación pasivo, no un módulo.", ["Un inyector PoE agrega energía a un cable Ethernet; es una caja externa, no un módulo que agregue soporte de fibra.", null, "Un panel de parcheo es un punto de terminación pasivo en rack para tendidos de cable, no un módulo insertable del switch.", "Un keystone es un jack de encaje para placas de pared o paneles; no se inserta en una ranura del switch."]],
  "cs35": ["¿Qué conector de fibra es pequeño, cuadrado y se encuentra comúnmente en pares en los módulos SFP?", ["BNC", "RJ-11", "F-type", "LC"], "LC es el conector de fibra de formato pequeño común en los SFP. BNC y F-type son conectores coaxiales.", ["BNC es un conector coaxial redondo de bayoneta, no un conector de fibra.", "RJ-11 es un conector telefónico de cobre, no de fibra.", "F-type es un conector coaxial roscado para TV por cable y módems.", null]],
  "cs36": ["Los usuarios cerca de una sala de descanso pierden el Wi-Fi de 2.4 GHz cada vez que funciona el horno de microondas. ¿Cuál es la mejor solución?", ["Mover a esos usuarios a la banda de 5 GHz", "Bajar el canal del AP a 1", "Cambiar la red a WEP", "Aumentar el tiempo de concesión DHCP para esas laptops"], "Los hornos de microondas interfieren en la banda de 2.4 GHz; 5 GHz evita esa interferencia. Cambiar la configuración de seguridad no hace nada ante la interferencia de radio.", [null, "El canal 1 sigue estando en la banda de 2.4 GHz, y los hornos de microondas interfieren en gran parte de esa banda, así que las caídas continuarían.", "WEP es una configuración de seguridad rota y no tiene efecto sobre la interferencia de radio.", "El tiempo de concesión DHCP controla cuánto tiempo se conserva una dirección; no puede evitar que la señal de radio quede ahogada."]],
  "cs37": ["¿Qué afirmación compara correctamente las redes celulares y Wi-Fi?", ["El Wi-Fi usa espectro licenciado y el celular no", "Ambos requieren un cable Ethernet al dispositivo", "El celular usa espectro licenciado operado por un carrier", "El celular se limita a un solo edificio"], "El celular (4G/5G) funciona en espectro licenciado a los carriers. El Wi-Fi usa bandas no licenciadas, así que la primera opción los invierte.", ["Esto invierte los hechos: el Wi-Fi usa bandas no licenciadas y el celular usa espectro licenciado.", "Ninguno necesita un cable Ethernet al dispositivo; ambas son tecnologías inalámbricas.", null, "Las redes celulares cubren áreas amplias mediante las torres del carrier; es el Wi-Fi el que típicamente se limita a un edificio."]],
  "cs38": ["¿Qué tres canales de 2.4 GHz no se solapan en Norteamérica?", ["1, 6 y 11", "2, 7 y 12", "1, 5 y 9", "3, 8 y 13"], "Los canales 1, 6 y 11 son el conjunto estándar de 2.4 GHz sin solapamiento en Norteamérica. Otras combinaciones se solapan.", [null, "Los canales 2, 7 y 12 están separados por 5 como 1/6/11 pero no son el conjunto estándar, y el canal 12 normalmente no se permite para Wi-Fi en Norteamérica.", "Los canales 1, 5 y 9 están separados solo por 4 canales, así que sus señales de 20 MHz se solapan.", "El canal 13 normalmente no se usa en Norteamérica, y 3/8/13 no es el plan estándar sin solapamiento."]],
  "cs39": ["Un visitante necesita unirse al Wi-Fi de invitados de la oficina usando WPA2-Personal. ¿Qué debe saber?", ["La dirección MAC y el número de serie del AP", "El SSID y la frase de contraseña (passphrase)", "El ID de VLAN del switch y la puerta de enlace", "Su nombre de usuario y una tarjeta inteligente"], "WPA2-Personal requiere el nombre de la red (SSID) y la frase de contraseña precompartida. Los inicios de sesión basados en usuario son para WPA2-Enterprise.", ["La dirección MAC y el número de serie del AP identifican el hardware; un cliente no los necesita para unirse.", null, "Los ID de VLAN y las puertas de enlace los asigna la red después de unirse; el visitante no los ingresa.", "Un nombre de usuario y una tarjeta inteligente son credenciales para WPA2-Enterprise con 802.1X, no para WPA2-Personal."]],
  "cs40": ["Un tendido de cable de cobre entre un switch y una PC tiene 130 metros de largo y el enlace está lento con muchos errores. ¿Cuál es el problema?", ["El cable es demasiado corto", "La PC necesita una IP estática", "El tendido excede el límite de 100 m de Ethernet", "El switch necesita un módulo SFP"], "El Ethernet de par trenzado se limita a 100 m; más allá, la atenuación causa errores. La configuración de IP no tiene nada que ver con la pérdida de señal.", ["El cable es demasiado largo, no demasiado corto; los cables cortos no causan errores en Ethernet.", "La pérdida de señal en un cable largo es un problema de la capa física; una IP estática no lo cambiaría.", null, "Un módulo SFP se usa para fibra o enlaces de subida de cobre especiales; el tendido de cobre existente simplemente es demasiado largo."]],
  "cs41": ["Un termostato inteligente, un sensor de puerta y una cámara de seguridad están todos en la red. ¿Qué categoría de endpoints son estos?", ["Servidores", "Clientes ligeros (thin clients)", "Estaciones de trabajo (workstations)", "Dispositivos IoT"], "Los dispositivos de Internet de las cosas (IoT) son sensores y aparatos conectados de propósito único. Los servidores brindan servicios a muchos clientes.", ["Los servidores brindan servicios como archivos o correo a muchos clientes, a diferencia de los sensores de propósito único.", "Los clientes ligeros son computadoras de bajo consumo que ejecutan un escritorio remoto, no sensores y aparatos.", "Las estaciones de trabajo son computadoras completas de usuario como escritorios, no dispositivos conectados de propósito único.", null]],
  "cs42": ["En una PC con Windows, ¿qué comando muestra la dirección IP, la máscara de subred, la puerta de enlace predeterminada, los servidores DNS y la dirección MAC?", ["ipconfig /all", "netstat -an", "ping -t", "tracert -d 8.8.8.8"], "ipconfig /all muestra la configuración completa del adaptador. El ipconfig simple omite los detalles de DNS y MAC, y netstat muestra las conexiones.", [null, "netstat -an lista las conexiones activas y los puertos en escucha, no la configuración de direcciones del adaptador.", "ping -t hace ping continuo a un host; prueba la accesibilidad y no muestra la configuración.", "tracert -d traza la ruta a un host sin búsquedas de nombres; no muestra la configuración del adaptador local."]],
  "cs43": ["Un usuario de Linux quiere ver las direcciones asignadas a cada interfaz. ¿Qué comando moderno debería ejecutar?", ["ipconfig /all", "ip addr", "show ip interface brief", "nslookup"], "ip addr (ip a) lista las interfaces y direcciones en Linux. ipconfig es el comando de Windows.", ["ipconfig /all es un comando de Windows y no existe en Linux.", null, "show ip interface brief es un comando de Cisco IOS, no un comando de Linux.", "nslookup consulta el DNS para la resolución de nombres; no lista las direcciones de las interfaces."]],
  "cs44": ["Un usuario de iPhone dice que el Wi-Fi aparece conectado pero las apps no cargan. ¿Dónde puede el técnico revisar la dirección IP del teléfono y la dirección del router?", ["La App Store", "La configuración de Bluetooth del teléfono", "La configuración de Wi-Fi, el icono de info junto a la red", "La configuración de Batería"], "En iOS, tocar el icono de información (i) junto a la red Wi-Fi conectada muestra la dirección IP, la máscara de subred y el router. La configuración de Bluetooth no muestra detalles de IP.", ["La App Store instala apps y no tiene detalles de configuración de red.", "La configuración de Bluetooth administra los dispositivos emparejados y no muestra la configuración IP de Wi-Fi.", null, "La configuración de Batería muestra el uso de energía, no las direcciones de red."]],
  "cs45": ["Un ingeniero pregunta qué está haciendo el LED de un puerto del switch, y el técnico reporta verde fijo que parpadea cuando se usa una PC. ¿Qué suele significar esto?", ["El puerto está deshabilitado", "El puerto tiene enlace y está pasando tráfico", "El puerto falló el POST", "El puerto está bloqueado por el Protocolo Spanning Tree"], "Verde significa enlace activo, y el verde parpadeante muestra actividad. El ámbar suele indicar bloqueado, deshabilitado o defectuoso.", ["Un puerto deshabilitado normalmente no muestra luz o muestra ámbar, no verde con actividad.", null, "Un POST fallido aparece en el LED del sistema, típicamente ámbar, no como un puerto verde con actividad.", "Un puerto bloqueado por STP muestra ámbar, no verde."]],
  "cs46": ["Un puerto de switch recién conectado permanece ámbar durante mucho tiempo, mientras que otros puertos se ponen verdes. ¿Qué debería reportar el técnico al ingeniero?", ["El puerto funciona normalmente a velocidad plena", "El presupuesto de PoE ha aumentado", "El puerto puede estar bloqueado, deshabilitado o defectuoso", "El firmware del switch está actualizado"], "Una luz de puerto ámbar fija en un switch Cisco comúnmente significa que el puerto está bloqueado (por ejemplo, por STP), deshabilitado o tiene una falla. Verde indicaría enlace normal.", ["Un puerto que funciona normalmente muestra verde, no ámbar prolongado.", "Las luces de puerto ámbar no indican el presupuesto de PoE, y los presupuestos de PoE no aumentan por sí solos.", null, "Los LED de los puertos no dicen nada sobre las versiones de firmware."]],
  "cs47": ["El LED del sistema en un switch Cisco está apagado y ninguna de las luces de los puertos está encendida. ¿Qué debería revisar el técnico primero?", ["El servidor DNS", "La configuración de VLAN", "El ámbito (scope) de DHCP", "La fuente de alimentación y el cable de energía"], "Si la luz del sistema está apagada, el switch probablemente no tiene energía. Los ajustes de VLAN y DHCP no pueden afectar el LED del sistema.", ["Un problema del servidor DNS no puede apagar los LED del sistema y de los puertos del switch.", "Los ajustes de VLAN cambian qué puertos comparten un dominio de broadcast pero no apagan los LED.", "Un ámbito de DHCP afecta las direcciones entregadas a los clientes, no las propias luces del switch.", null]],
  "cs48": ["Un ingeniero envía un diagrama que muestra SW1 Gi1/0/24 conectándose a R1 G0/0. ¿Qué debería hacer el técnico?", ["Conectar un cable de parcheo del puerto Gi1/0/24 en SW1 al puerto G0/0 en R1", "Conectar cualquier puerto libre del switch al puerto de consola del router", "Conectar el puerto 1 de SW1 al puerto 24 de R1", "Conectar el puerto USB de R1 a la primera ranura SFP libre en SW1 usando un cable de consola"], "Los diagramas listan el dispositivo y la interfaz exactos en cada extremo de un enlace, así que el cable va de SW1 Gi1/0/24 a R1 G0/0. Conectar cualquier puerto libre no coincidiría con el diseño.", [null, "El puerto de consola es para administración, y el diagrama pide un enlace de datos específico entre interfaces nombradas.", "Esto intercambia los números de puerto; el diagrama nombra Gi1/0/24 en SW1 y G0/0 en R1.", "Un cable de consola es para administración por CLI y no puede crear un enlace de datos enrutado hacia una ranura SFP."]],
  "cs49": ["Después de parchear un cable del diagrama, el técnico quiere confirmar que está en el puerto correcto sin iniciar sesión. ¿Cuál es la verificación más rápida?", ["Reiniciar el switch", "Buscar que la luz de enlace del puerto esperado se ponga verde", "Reemplazar el panel de parcheo", "Cambiar la VLAN del puerto"], "El LED del puerto muestra el enlace en cuanto se conecta el otro extremo, confirmando la conexión física. Reiniciar interrumpe a los usuarios y no prueba nada.", ["Reiniciar el switch interrumpe a todos los usuarios y no muestra en qué puerto está el cable.", null, "Reemplazar el panel de parcheo es un cambio mayor y no hace nada para confirmar la nueva conexión.", "Cambiar la VLAN es un cambio de configuración que podría romper el puerto; no verifica el parcheo físico."]],
  "cs50": ["¿Qué puerto se usa para administrar un router Cisco nuevo que aún no tiene una dirección IP configurada?", ["Un puerto SFP", "Un puerto PoE", "El puerto de consola", "Un puerto serial WAN"], "El puerto de consola da acceso CLI fuera de banda sin necesidad de IP. Los puertos seriales se conectan a enlaces WAN, no a terminales de administración.", ["Un puerto SFP es un puerto de datos para módulos de fibra o cobre y necesita configuración IP para usarse en administración.", "Un puerto PoE es un puerto de datos que además suministra energía; no es un puerto de administración fuera de banda.", null, "Un puerto serial se conecta a circuitos WAN, no a la terminal de un técnico."]],
  "cs51": ["Un teléfono VoIP no tiene adaptador de corriente pero se enciende al conectarse al switch. ¿Qué función está brindando el puerto del switch?", ["Power over Ethernet (PoE)", "Seguridad de puerto (port security)", "Agregación de enlaces (link aggregation)", "Trunking de VLAN"], "PoE entrega energía por el cable Ethernet a teléfonos, APs y cámaras. El trunking transporta VLANs pero no energía.", [null, "La seguridad de puerto limita qué direcciones MAC pueden usar un puerto; no suministra energía.", "La agregación de enlaces agrupa varios enlaces para más ancho de banda; no alimenta dispositivos.", "El trunking transporta múltiples VLANs sobre un enlace pero no entrega energía."]],
  "cs52": ["¿Qué cable conecta el puerto USB de una laptop al puerto de consola RJ-45 de un switch Cisco?", ["Un cable cruzado (crossover) Cat 6", "Un puente coaxial", "Un cable de fibra monomodo", "Un cable de consola (rollover) USB a RJ-45"], "El acceso por consola usa un cable de consola tipo rollover, a menudo USB a RJ-45. Un crossover es para enlaces Ethernet, no para acceso por consola.", ["Un cable crossover conecta dispositivos Ethernet directamente; no proporciona una conexión de consola serial.", "Los puentes coaxiales son para TV por cable y módems, no para puertos de consola Cisco.", "La fibra monomodo transporta datos a largas distancias y no tiene función de consola.", null]],
  "cs53": ["Una PC puede alcanzar otras PC de su subred pero nada en otras redes. Su IP y máscara son correctas. ¿Cuál es el ajuste faltante más probable?", ["Sufijo DNS", "Puerta de enlace predeterminada", "Dirección MAC", "Número de puerto del servidor proxy"], "La puerta de enlace predeterminada es a donde un host envía el tráfico para redes remotas. Un ajuste DNS faltante todavía permitiría hacer ping a direcciones IP remotas.", ["Un sufijo DNS faltante afecta el completado de nombres, pero la PC aún podría alcanzar redes remotas por IP.", null, "Toda tarjeta de red ya tiene una dirección MAC grabada; no es un ajuste que el usuario configure.", "Un ajuste de proxy afecta solo el tráfico web a través de un proxy y no bloquearía todas las redes remotas."]],
  "cs54": ["La PC 10.0.5.10/24 envía un paquete a 10.0.9.20. ¿A dónde envía la PC la trama?", ["Directamente a la dirección MAC de 10.0.9.20", "Al servidor DNS", "A todos los hosts como broadcast", "A la dirección MAC de su puerta de enlace predeterminada"], "10.0.9.20 está fuera de 10.0.5.0/24, así que la PC envía la trama a su puerta de enlace, que la enruta. No puede alcanzar la MAC del host remoto directamente.", ["El destino está en una red diferente, así que la PC no puede hacer ARP ni alcanzar su MAC directamente.", "El servidor DNS resuelve nombres; los paquetes a una dirección IP no se envían a través de él.", "El tráfico unicast a un host remoto no se difunde; solo la solicitud ARP para la puerta de enlace podría serlo.", null]],
  "cs55": ["¿Qué puede hacer un switch de Capa 3 que un switch de Capa 2 no puede?", ["Enrutar tráfico entre VLANs o subredes", "Aprender direcciones MAC", "Reenviar tramas dentro de una VLAN", "Brindar Power over Ethernet a los teléfonos IP"], "Un switch de Capa 3 puede enrutar usando direcciones IP. Aprender MACs y reenviar dentro de una VLAN son funciones básicas de Capa 2 que ambos realizan.", [null, "Tanto los switches de Capa 2 como los de Capa 3 aprenden direcciones MAC de las direcciones de origen.", "Reenviar tramas dentro de una VLAN es una función básica de un switch de Capa 2.", "Muchos switches de Capa 2 también brindan PoE; no está ligado a la capacidad de enrutar."]],
  "cs56": ["¿Qué dispositivo separa redes y reenvía paquetes entre ellas usando direcciones IP?", ["Hub", "Switch no administrado", "Router", "Punto de acceso (access point)"], "Los routers conectan redes diferentes y toman decisiones por dirección IP. Un switch no administrado solo reenvía por MAC dentro de una red.", ["Un hub repite los bits por todos los puertos y no entiende de direcciones IP.", "Un switch no administrado reenvía tramas por dirección MAC dentro de una red, no entre redes.", null, "Un punto de acceso puentea clientes inalámbricos a la LAN; no enruta entre redes por IP."]],
  "cs57": ["¿Cómo aprende un switch a qué puerto está conectado un dispositivo?", ["Le pregunta al servidor DNS", "Lee la dirección MAC de origen de las tramas que llegan a cada puerto", "Lee la dirección IP de destino de cada paquete", "El administrador escribe cada entrada manualmente"], "Los switches registran la MAC de origen y el puerto de entrada de cada trama en la tabla de direcciones MAC. Las IP de destino las usan los routers, no para el aprendizaje de MAC.", ["DNS mapea nombres a direcciones IP; los switches nunca preguntan al DNS por las ubicaciones de los puertos.", null, "Los switches de Capa 2 no leen direcciones IP, y el aprendizaje usa la dirección de origen, no la de destino.", "Las entradas estáticas son posibles pero rara vez se usan; los switches aprenden las entradas automáticamente."]],
  "cs58": ["Un switch recibe una trama para una dirección MAC que no está en su tabla de direcciones MAC. ¿Qué hace?", ["Descarta la trama", "La devuelve al remitente", "La envía solo a la puerta de enlace predeterminada", "La inunda por todos los puertos de la VLAN excepto el que llegó"], "Las tramas unicast desconocidas se inundan dentro de la VLAN para que el destino pueda recibirlas. Descartarla rompería las conversaciones nuevas.", ["Descartar las tramas unicast desconocidas rompería toda conversación nueva antes de que se aprendiera la MAC.", "Un switch nunca envía una trama de vuelta por el puerto por el que llegó.", "Un switch de Capa 2 no tiene concepto de una puerta de enlace predeterminada para reenviar tramas.", null]],
  "cs59": ["Una oficina quiere que los dispositivos de invitados y las PC del personal estén en los mismos switches pero en dominios de broadcast separados. ¿Qué debería configurarse?", ["VLANs", "Un ámbito DHCP más grande", "Enlaces de subida más rápidos", "Solo un nuevo SSID"], "Las VLANs dividen un switch físico en dominios de broadcast separados. Un ámbito DHCP más grande solo agrega direcciones, no separa el tráfico.", [null, "Un ámbito DHCP más grande solo proporciona más direcciones; todos los dispositivos seguirían compartiendo un dominio de broadcast.", "Los enlaces de subida más rápidos agregan ancho de banda pero no separan el tráfico.", "Un SSID por sí solo no separa el tráfico cableado, y sin VLANs los invitados y el personal seguirían compartiendo una red."]],
  "cs60": ["Dos PC están en el mismo switch pero en VLANs diferentes. ¿Qué se necesita para que se comuniquen?", ["Un cable de parcheo más largo", "Un router o un switch de Capa 3", "Un hub entre ellas", "La misma dirección MAC en ambas"], "Cada VLAN es su propia red, así que el tráfico entre ellas debe enrutarse. Un hub no puede unir VLANs.", ["La longitud del cable no tiene efecto sobre la separación de VLANs.", null, "Un hub opera en la Capa 1 y no puede mover tráfico entre VLANs.", "Las direcciones MAC duplicadas causarían problemas y aun así no unirían dos VLANs."]],
  "cs61": ["Un puerto de switch se conecta a otro switch y debe transportar tráfico de las VLANs 10, 20 y 30. ¿Cómo debería configurarse el puerto?", ["Como puerto de acceso en la VLAN 10", "Como puerto de consola", "Como puerto troncal (trunk)", "Como puerto apagado (shutdown)"], "Los puertos troncales transportan varias VLANs usando etiquetas 802.1Q. Un puerto de acceso pertenece a una sola VLAN.", ["Un puerto de acceso pertenece a una sola VLAN, así que las VLANs 20 y 30 no podrían cruzar el enlace.", "Un puerto de consola es para administración por CLI, no para transportar tráfico de usuario entre switches.", null, "Un puerto apagado no pasa tráfico alguno."]],
  "cs62": ["Un ingeniero pide al técnico revisar qué puerto de switch está usando una PC con una dirección MAC conocida. ¿Qué comando debería ejecutarse?", ["show version", "show mac address-table", "show ip route", "show running-config | include hostname"], "show mac address-table lista cada MAC aprendida con su VLAN y puerto. show version muestra software y hardware, no las ubicaciones de las MAC.", ["show version muestra la versión de software, el tiempo activo y detalles de hardware, no los mapeos de MAC a puerto.", null, "show ip route muestra la tabla de enrutamiento de redes IP, no dónde están conectadas las direcciones MAC.", "Esto solo muestra la línea del hostname de la configuración, que no tiene nada que ver con las ubicaciones de las MAC."]],
  "cs63": ["Un usuario reporta que el correo dejó de funcionar. ¿Cuál es el primer paso de la metodología de resolución de problemas?", ["Identificar el problema recopilando información y haciendo preguntas", "Reemplazar el cable de red del usuario y reiniciar la PC para ver si ayuda", "Reiniciar el servidor de correo", "Documentar la solución en el ticket"], "La resolución de problemas comienza por identificar el problema: síntomas, alcance y cambios recientes. Reemplazar hardware primero omite el diagnóstico.", [null, "Reemplazar hardware y reiniciar son correcciones intentadas antes de entender el problema, omitiendo el diagnóstico.", "Reiniciar el servidor de correo es una corrección no probada que podría interrumpir a todos los usuarios.", "La documentación es el último paso, después de que el problema se corrige y se verifica."]],
  "cs64": ["Un técnico corrige el mapeo de una impresora de un usuario. ¿Qué paso debería ir antes de cerrar el ticket?", ["Establecer una teoría de la causa probable", "Escalar al equipo de red", "Verificar la funcionalidad completa y documentar la solución", "Preguntar al usuario qué cambió"], "Después de una corrección, verifica que funcione para el usuario y documenta lo que se hizo. Establecer una teoría ocurre antes en el proceso.", ["Establecer una teoría es el segundo paso, hecho antes de la corrección, no después.", "El escalamiento es para problemas que no puedes resolver; este ya está corregido.", null, "Preguntar al usuario corresponde al primer paso, identificar el problema."]],
  "cs65": ["Llegan dos tickets al mismo tiempo: un usuario no puede cambiar el fondo de pantalla del escritorio, y todo el piso de ventas perdió el internet. ¿Cómo deberían manejarse?", ["En el orden en que se recibieron", "El que sea más fácil primero", "El fondo de pantalla primero porque es rápido", "La caída del piso de ventas primero porque afecta a más personas y al negocio"], "La prioridad se basa en el impacto y la urgencia; una caída que afecta a todo un departamento supera un problema cosmético de un solo usuario. El orden de llegada ignora el impacto.", ["El orden de llegada ignora el impacto y la urgencia, dejando todo un departamento caído detrás de una solicitud cosmética.", "Elegir el trabajo más fácil primero ignora el impacto al negocio.", "Una corrección rápida del problema cosmético de un usuario no debería retrasar restaurar el servicio a todo un departamento.", null]],
  "cs66": ["Un técnico de mesa de ayuda no puede corregir un problema de switch y lo escala. ¿Qué hace que el escalamiento sea más útil?", ["Un ticket con síntomas, usuarios afectados, pruebas realizadas y resultados", "Un mensaje corto que dice que la red está rota", "Una llamada telefónica sin ticket", "Pedir al usuario que llame directamente al ingeniero de red y le explique el problema"], "Notas claras sobre síntomas, alcance y pasos ya intentados evitan que el siguiente nivel repita el trabajo. Un mensaje vago los obliga a empezar de cero.", [null, "Un mensaje vago obliga al siguiente nivel a empezar de nuevo desde cero.", "Una llamada telefónica sin ticket no deja registro para seguimiento ni revisión posterior.", "Empujar al usuario a explicarlo él mismo pierde detalle técnico y traslada el trabajo de la mesa de ayuda al usuario."]],
  "cs67": ["Un técnico quiere capturar tráfico en Wireshark desde la conexión cableada de una laptop. ¿Qué debe seleccionarse antes de empezar?", ["Un filtro de visualización (display filter)", "La interfaz de red correcta", "El formato de archivo .txt", "La dirección IP del router"], "Wireshark captura en la interfaz que selecciones, así que elige el adaptador cableado. Los filtros de visualización pueden aplicarse después de capturar.", ["Un filtro de visualización solo oculta paquetes en pantalla y puede aplicarse después de capturar; no decide qué se captura.", null, "Wireshark guarda las capturas como .pcapng o .pcap, y el formato de archivo se elige al guardar, no antes de capturar.", "La dirección IP del router no se requiere para iniciar una captura en una interfaz local."]],
  "cs68": ["Después de una captura, el técnico quiere ver solo el tráfico DNS en Wireshark. ¿Qué debería escribirse en la barra de filtro de visualización?", ["port 53 only", "show dns", "dns", "filter=dns"], "El filtro de visualización dns de Wireshark muestra los paquetes DNS. Las otras entradas no son sintaxis válida de filtro de visualización.", ["port 53 only no es sintaxis válida de Wireshark; la forma del filtro de visualización sería udp.port == 53 o tcp.port == 53.", "show dns no es un filtro de Wireshark; parece un comando de CLI de dispositivo.", null, "filter=dns no es sintaxis válida de filtro de visualización; se escribe el propio nombre del protocolo."]],
  "cs69": ["Un ingeniero pide una captura de paquetes para revisarla más tarde. ¿Cómo debería compartirla el técnico?", ["Tomar una captura de pantalla de la lista de paquetes", "Copiar la línea de resumen en el ticket", "Exportarla como un CSV de las IP de origen", "Guardarla como un archivo .pcapng y adjuntarla"], "Guardar la captura como .pcapng conserva cada paquete para que el ingeniero pueda abrirla en Wireshark. Una captura de pantalla pierde los detalles de los paquetes.", ["Una captura de pantalla muestra solo las líneas de resumen visibles y pierde el contenido completo de los paquetes que el ingeniero necesita.", "Una sola línea de resumen omite los encabezados y la carga útil de cada paquete.", "Un CSV de IP de origen descarta puertos, banderas, tiempos y cargas útiles, así que el ingeniero no puede analizar el tráfico.", null]],
  "cs70": ["ping 8.8.8.8 tiene éxito, pero ping www.example.com dice que no pudo encontrar el host. ¿Qué área es la que más probablemente está fallando?", ["Resolución de nombres (DNS)", "El cable físico", "El ajuste de la puerta de enlace predeterminada", "La contraseña de Wi-Fi"], "Alcanzar una dirección IP prueba que la ruta y la puerta de enlace funcionan; fallar por nombre apunta al DNS. Una falla de cable o de puerta de enlace también rompería el ping por IP.", [null, "Una falla de cable rompería también el ping a 8.8.8.8, y ese ping tuvo éxito.", "Una puerta de enlace faltante o incorrecta detendría el ping a 8.8.8.8, que es una dirección remota.", "Una contraseña de Wi-Fi incorrecta impediría la conexión por completo, así que ningún ping tendría éxito."]],
  "cs71": ["Un usuario no puede alcanzar un sitio web. tracert muestra respuestas de los primeros tres saltos, luego solo asteriscos. ¿Qué sugiere esto?", ["La PC del usuario no tiene dirección IP", "El problema, o un dispositivo que bloquea ICMP, está más allá del tercer salto", "El servidor DNS está caído", "La contraseña de Wi-Fi es incorrecta"], "Los primeros saltos respondieron, así que el enlace local y la puerta de enlace funcionan; el problema o un firewall que descarta las sondas de traceroute está más adelante en la ruta. Una PC sin IP no obtendría respuestas en absoluto.", ["Una PC sin dirección IP no obtendría respuestas en absoluto, pero los primeros tres saltos respondieron.", null, "tracert a una IP se ejecuta sin DNS, y una caída de DNS no haría que los saltos dejaran de responder a mitad de la ruta.", "Una contraseña de Wi-Fi incorrecta impediría cualquier conexión, así que ningún salto respondería."]],
  "cs72": ["El sitio web de un servidor carga bien en un navegador, pero el ping al servidor agota el tiempo de espera. ¿Cuál es la explicación más probable?", ["La tarjeta de red del servidor está desconectada", "Falta el registro DNS del servidor", "Un firewall está bloqueando las solicitudes de eco ICMP", "El servidor está apagado"], "Los firewalls a menudo bloquean ICMP mientras permiten el tráfico web, así que un ping fallido no significa que el servicio esté caído. Un servidor desconectado o apagado no serviría la página.", ["Una tarjeta de red desconectada también impediría que el sitio web cargara.", "Un registro DNS faltante impediría que el navegador encontrara el sitio por nombre, pero el sitio carga bien.", null, "Un servidor apagado no podría servir la página web."]],
  "cs73": ["¿Qué comando verifica si un servidor DNS puede resolver un nombre de host a una dirección IP?", ["arp -a", "ipconfig /release", "netstat", "nslookup"], "nslookup consulta directamente a un servidor DNS. arp -a muestra la caché local de IP a MAC y no prueba el DNS.", ["arp -a muestra la caché local de mapeos de IP a MAC y no consulta el DNS.", "ipconfig /release libera la dirección DHCP de la PC; no prueba la resolución de nombres.", "netstat lista las conexiones de red y los puertos en escucha, no las búsquedas DNS.", null]],
  "cs74": ["Un técnico ejecuta ping 127.0.0.1 en una PC y obtiene respuestas. ¿Qué confirma esto?", ["La pila TCP/IP de la PC funciona", "La puerta de enlace predeterminada es alcanzable", "El servidor DNS está respondiendo", "La conexión a internet está activa"], "127.0.0.1 es la dirección de loopback, así que la respuesta muestra solo que la pila IP local funciona. Nunca sale de la PC, así que no dice nada sobre la puerta de enlace.", [null, "El tráfico de loopback nunca sale de la PC, así que no dice nada sobre alcanzar la puerta de enlace.", "Hacer ping a 127.0.0.1 no contacta al servidor DNS en absoluto.", "Las respuestas de loopback solo prueban que la pila local funciona, no que el enlace a internet esté activo."]],
  "cs75": ["Un ingeniero necesita administrar un switch de forma remota con una sesión de línea de comandos cifrada. ¿Qué protocolo debería usarse?", ["Telnet", "SSH", "RDP", "TFTP"], "SSH proporciona una sesión CLI cifrada en TCP 22. Telnet envía todo, incluidas las contraseñas, en texto claro.", ["Telnet proporciona acceso CLI pero envía todo, incluidas las contraseñas, en texto claro.", null, "RDP es para escritorios gráficos de Windows, no para la administración por línea de comandos de un switch.", "TFTP transfiere archivos como configuraciones e imágenes y no es una sesión interactiva."]],
  "cs76": ["Un técnico necesita ver el escritorio de un servidor Windows desde casa para cambiar un ajuste. ¿Qué herramienta encaja?", ["Cable de consola serial con PuTTY", "SSH", "Remote Desktop Protocol (RDP)", "SNMP"], "RDP da un escritorio gráfico remoto en Windows. SSH proporciona acceso por línea de comandos, no el escritorio de Windows.", ["Un cable de consola serial debe estar conectado físicamente al dispositivo y da una CLI, no un escritorio de Windows desde casa.", "SSH da una sesión de línea de comandos, no el escritorio gráfico de Windows que el técnico necesita.", null, "SNMP monitorea y administra dispositivos con valores consultados; no muestra un escritorio."]],
  "cs77": ["Los switches y puntos de acceso de una empresa se administran desde un panel web alojado por el proveedor, sin un controlador en el sitio. ¿Cómo se llama este enfoque?", ["Administración por consola fuera de banda", "Administración por Telnet", "Un servidor TFTP local", "Administración de red basada en la nube"], "Las plataformas administradas en la nube como Cisco Meraki permiten a los administradores configurar y monitorear dispositivos desde un panel alojado. La administración por consola requiere un cable físico.", ["La administración por consola fuera de banda usa un cable de consola físico o una red de administración separada, no un panel alojado por el proveedor.", "Telnet es un protocolo de línea de comandos sin cifrar, no un panel web alojado.", "Un servidor TFTP local almacena configuraciones e imágenes en el sitio y no ofrece un panel central.", null]],
  "cs78": ["Un trabajador remoto debe alcanzar recursos compartidos de archivos internos de forma segura por internet. ¿Con qué debería conectarse primero?", ["Una VPN", "Telnet", "FTP", "Un Wi-Fi de invitados abierto"], "Una VPN crea un túnel cifrado hacia la red de la empresa. FTP envía los datos sin cifrar y no proporciona acceso a la red.", [null, "Telnet es un protocolo remoto de CLI sin cifrar y no da acceso seguro a los recursos compartidos de archivos.", "FTP envía las credenciales y los datos sin cifrar y no proporciona acceso a la red interna.", "Un Wi-Fi de invitados abierto no está cifrado y no conecta al usuario con la red de la empresa."]],
  "cs79": ["¿Qué comando de Cisco da una lista corta de cada interfaz con su dirección IP y su estado activo/inactivo (up/down)?", ["show running-config", "show version", "show ip interface brief", "show cdp neighbors"], "show ip interface brief muestra una línea por interfaz con IP, estado y protocolo. show running-config muestra toda la configuración y es mucho más largo.", ["show running-config imprime toda la configuración, no un resumen de estado de una línea por interfaz.", "show version muestra software, tiempo activo y detalles de hardware, no la IP y el estado por interfaz.", null, "show cdp neighbors lista los dispositivos Cisco conectados directamente, no las direcciones IP y el estado de las interfaces."]],
  "cs80": ["Un ingeniero pregunta qué dispositivos Cisco están conectados directamente al switch y en qué puertos. ¿Qué comando responde esto?", ["show ip route", "show cdp neighbors", "show inventory", "show interfaces status"], "CDP descubre los dispositivos Cisco conectados directamente, mostrando sus nombres, plataformas y puertos locales. show ip route lista rutas, no vecinos.", ["show ip route lista las redes conocidas y los próximos saltos, no los dispositivos conectados directamente por puerto.", null, "show inventory lista las partes de hardware y los números de serie del propio dispositivo, no sus vecinos.", "show interfaces status muestra el estado, VLAN, dúplex y velocidad de cada puerto, pero no qué dispositivo está conectado."]],
  "cs81": ["Se le pide a un técnico la versión de IOS del switch y cuánto tiempo lleva funcionando desde la última recarga. ¿Qué comando muestra ambos?", ["show version", "show running-config", "show mac address-table", "show ip interface brief"], "show version muestra la versión de IOS, el tiempo activo, el modelo y más. La configuración en ejecución no muestra el tiempo activo.", [null, "show running-config muestra la configuración actual pero no el tiempo activo.", "show mac address-table muestra las direcciones MAC aprendidas y los puertos, no la versión ni el tiempo activo.", "show ip interface brief resume las interfaces e IP, no la versión de IOS ni el tiempo activo."]],
  "cs82": ["El prompt del switch muestra Switch>. ¿Qué debe escribirse para llegar al modo EXEC privilegiado y ejecutar más comandos show?", ["configure terminal", "exit", "show privilege", "enable"], "enable pasa de EXEC de usuario (>) a EXEC privilegiado (#). configure terminal solo funciona una vez que ya estás en modo privilegiado.", ["configure terminal entra al modo de configuración global y solo funciona desde EXEC privilegiado, no desde el prompt >.", "exit sale de la sesión o del modo actual; no eleva el privilegio.", "show privilege muestra el nivel de privilegio actual pero no lo cambia.", null]],
  "cs83": ["Un técnico olvida la sintaxis exacta de un comando show en un switch Cisco. ¿Cuál es la ayuda integrada más rápida?", ["Recargar el switch", "Escribir show ? para listar las opciones", "Escribir help show all", "Desconectar el cable de consola"], "Escribir ? lista las opciones válidas en ese punto del comando, y Tab completa palabras parciales. help show all no es sintaxis de IOS.", ["Recargar el switch interrumpe la red y no da ayuda con la sintaxis de comandos.", null, "help show all no es sintaxis válida de IOS; IOS usa ? para la ayuda contextual.", "Desconectar el cable de consola termina la sesión y no da ninguna ayuda."]],
  "cs84": ["show interfaces en un puerto muestra un conteo que aumenta constantemente de errores CRC. ¿Qué indica esto con mayor probabilidad?", ["Asignación de VLAN incorrecta", "Una mala configuración de DNS", "Un problema de cableado o de la capa física", "El puerto no tiene dirección IP"], "Los errores CRC significan que las tramas llegan corruptas, normalmente por cables, conectores o interferencia defectuosos. Los ajustes de DNS y VLAN no corrompen tramas.", ["Una VLAN incorrecta impide que el tráfico llegue a la red correcta pero no corrompe tramas ni causa errores CRC.", "Los problemas de DNS afectan la resolución de nombres por encima de la Capa 3 y no pueden corromper tramas en un enlace.", null, "Los puertos de switch normalmente no tienen dirección IP, y la falta de ajustes IP no causa errores de suma de comprobación en las tramas."]],
  "cs85": ["Una lista de reglas de firewall no tiene ninguna regla que coincida con una nueva conexión entrante. ¿Qué le pasa al tráfico?", ["Se permite por defecto", "Se registra y se reenvía", "Se envía al servidor DNS", "Se descarta por la denegación implícita (implicit deny)"], "Los firewalls terminan con una denegación implícita, así que el tráfico sin coincidencia se bloquea. Permitir el tráfico sin coincidencia anularía la lista de reglas.", ["Los firewalls bloquean por defecto el tráfico sin coincidencia; permitirlo por defecto anularía la lista de reglas.", "El tráfico sin coincidencia se descarta; puede registrarse, pero no se reenvía.", "Los firewalls no envían el tráfico sin coincidencia al servidor DNS.", null]],
  "cs86": ["El firewall de una oficina pequeña permite a los usuarios navegar por la web, y el tráfico de respuesta regresa automáticamente sin una regla entrante. ¿Qué función permite esto?", ["Inspección con estado (stateful inspection)", "Filtrado de MAC", "Espejeo de puertos (port mirroring)", "DHCP snooping en la LAN"], "Un firewall con estado rastrea las sesiones salientes y permite el tráfico de retorno correspondiente. El filtrado de MAC controla qué dispositivos pueden unirse, no el tráfico de retorno.", [null, "El filtrado de MAC controla qué dispositivos pueden conectarse; no rastrea sesiones para permitir el tráfico de retorno.", "El espejeo de puertos copia el tráfico a un puerto de monitoreo para análisis y no permite tráfico.", "El DHCP snooping bloquea servidores DHCP no autorizados en un switch; no gestiona el tráfico de retorno a través de un firewall."]],
  "cs87": ["Un administrador quiere impedir que alguien fuera de la red use Telnet para alcanzar dispositivos internos. ¿Qué regla de firewall encaja?", ["Permitir TCP 23 desde cualquier origen", "Denegar TCP 23 desde el exterior", "Denegar UDP 53 desde el exterior", "Permitir TCP 443 desde cualquier origen"], "Telnet usa TCP 23, así que denegarlo en la entrada bloquea el acceso Telnet desde afuera. UDP 53 es DNS.", ["Permitir TCP 23 desde cualquier origen permitiría el acceso Telnet desde afuera, lo opuesto del objetivo.", null, "UDP 53 es DNS; bloquearlo rompería la resolución de nombres y no detendría Telnet.", "TCP 443 es HTTPS; permitirlo no hace nada para bloquear Telnet."]],
  "cs88": ["Un atacante cambia los montos en una transferencia bancaria mientras está en tránsito. ¿Qué parte de la tríada CIA se ve afectada?", ["Confidencialidad", "Disponibilidad", "Integridad", "Rendición de cuentas (accountability)"], "Los cambios no autorizados a los datos dañan la integridad. La confidencialidad se refiere a que los datos sean leídos por las personas equivocadas.", ["La confidencialidad se refiere a que los datos sean vistos por personas no autorizadas, pero aquí los datos fueron cambiados.", "La disponibilidad se refiere a que los sistemas y datos sean alcanzables cuando se necesitan, no a que los datos sean alterados.", null, "La rendición de cuentas (rastrear acciones a los usuarios) no es parte de la tríada CIA y no describe datos alterados."]],
  "cs89": ["Un servidor web tiene un fallo sin parchear que los atacantes podrían usar. ¿Cómo se llama el fallo sin parchear?", ["Una amenaza (threat) de seguridad", "Un riesgo", "Un exploit", "Una vulnerabilidad"], "Una vulnerabilidad es una debilidad. El exploit es el código o método que la usa, y la amenaza es quién o qué podría usarla.", ["Una amenaza es la persona o el evento que podría aprovechar una debilidad, no la debilidad en sí.", "El riesgo es la probabilidad y el impacto de que una amenaza use una debilidad, no el fallo en sí.", "Un exploit es el código o la técnica que aprovecha el fallo, no el fallo.", null]],
  "cs90": ["Miles de computadoras infectadas inundan el sitio web de una empresa con tráfico hasta que deja de responder. ¿Qué tipo de ataque es este?", ["DDoS", "Phishing", "Man-in-the-middle", "Tailgating"], "Un ataque de denegación de servicio distribuido usa muchos sistemas para saturar un objetivo y daña la disponibilidad. El phishing engaña a los usuarios con mensajes falsos.", [null, "El phishing usa mensajes falsos para engañar a los usuarios y que entreguen credenciales, no inundaciones de tráfico.", "Un ataque man-in-the-middle intercepta o altera el tráfico entre dos partes en lugar de saturar un servidor.", "El tailgating es un ataque físico donde alguien sigue a una persona autorizada a través de una puerta segura."]],
  "cs91": ["Un empleado recibe un correo que parece ser de TI, pidiéndole hacer clic en un enlace y volver a ingresar su contraseña. ¿Qué es esto?", ["Ransomware", "Phishing", "Un ataque DoS", "Un ataque de fuerza bruta"], "El phishing usa mensajes falsos para robar credenciales o instalar malware. La fuerza bruta adivina contraseñas en lugar de pedirlas.", ["El ransomware cifra archivos y exige un pago; este correo intenta obtener una contraseña.", null, "Un ataque DoS satura un sistema para dejarlo no disponible, no para engañar a un usuario.", "La fuerza bruta adivina contraseñas automáticamente en lugar de pedir al usuario que escriba una."]],
  "cs92": ["Un malware cifra los archivos de un usuario y muestra una exigencia de pago para desbloquearlos. ¿Qué tipo de malware es este?", ["Un keylogger", "Adware", "Ransomware", "Un rootkit"], "El ransomware cifra los datos y exige un pago. Un keylogger registra las pulsaciones de teclas pero no bloquea archivos.", ["Un keylogger registra en secreto las pulsaciones de teclas, pero no cifra archivos ni exige pago.", "El adware muestra anuncios no deseados; no bloquea archivos para pedir rescate.", null, "Un rootkit se oculta en lo profundo del sistema para mantener acceso oculto, pero normalmente no cifra archivos para pedir pago."]],
  "cs93": ["Un cliente está configurando un router doméstico nuevo. ¿Qué opción de seguridad inalámbrica debería recomendar el técnico?", ["WPA3-Personal", "WEP", "Abierta con SSID oculto", "WPA con TKIP"], "WPA3-Personal es la opción actual y más fuerte para hogares. WEP y TKIP están rotos, y ocultar un SSID no brinda seguridad real.", [null, "WEP está roto y puede descifrarse en minutos, así que nunca debería usarse.", "El Wi-Fi abierto envía el tráfico sin cifrar, y un SSID oculto se descubre fácilmente a partir de las sondas de los clientes.", "WPA con TKIP está obsoleto y tiene debilidades conocidas, así que no es una opción recomendada."]],
  "cs94": ["Un router doméstico ofrece un ajuste con botón para conectar dispositivos sin escribir la frase de contraseña. ¿Por qué debería normalmente desactivarse?", ["Obliga a los clientes a usar 6 GHz", "Reduce el alcance del Wi-Fi", "Cambia el SSID y el canal cada día automáticamente", "WPS puede ser atacado para revelar la clave de la red"], "Wi-Fi Protected Setup, especialmente el método de PIN, tiene debilidades conocidas que pueden filtrar la frase de contraseña. No tiene efecto sobre el alcance ni la banda.", ["WPS no tiene nada que ver con qué banda usan los clientes.", "WPS no afecta la potencia de transmisión ni el alcance de la radio.", "WPS no rota el SSID ni el canal; esos permanecen como esté configurado el router.", null]],
  "cs95": ["¿Cuál es la diferencia principal entre WPA2-Personal y WPA2-Enterprise?", ["Personal usa AES y Enterprise usa WEP", "Enterprise autentica a cada usuario mediante 802.1X, Personal usa una sola frase de contraseña compartida", "Personal funciona solo en 5 GHz", "Enterprise no necesita contraseñas en absoluto"], "El modo Enterprise verifica credenciales individuales contra un servidor de autenticación con 802.1X, mientras que Personal usa una clave precompartida. Ambos usan AES, no WEP.", ["Ambos modos normalmente usan AES; WEP es un protocolo separado y obsoleto, no parte de WPA2-Enterprise.", null, "WPA2-Personal funciona tanto en 2.4 GHz como en 5 GHz.", "Enterprise usa credenciales por usuario como nombres de usuario y contraseñas o certificados, así que no está libre de contraseñas por diseño."]],
  "cs96": ["Después de habilitar WPA3 en un router doméstico, una impresora antigua ya no puede unirse. ¿Cuál es una solución razonable que mantiene la seguridad fuerte?", ["Cambiar el router a WEP", "Desactivar por completo la seguridad del Wi-Fi", "Usar el modo de transición WPA2/WPA3 o conectar la impresora por cable", "Compartir la contraseña de administrador del router con la impresora"], "El modo de transición permite que los dispositivos WPA2 antiguos se unan mientras los más nuevos usan WPA3, y un cable evita el Wi-Fi por completo. WEP o Wi-Fi abierto expondrían toda la red.", ["WEP está roto y expondría todos los dispositivos de la red.", "Desactivar la seguridad permite que cualquiera se una y lea el tráfico.", null, "La contraseña de administrador del router controla los ajustes del router; una impresora no la usa y compartirla debilita la seguridad."]],
  "x1": ["Durante una llamada VoIP, los paquetes de voz llegan a intervalos desiguales, así que el audio suena entrecortado aunque el retardo promedio es bajo. ¿Cómo se llama esta variación en el retardo?", ["Latencia", "Jitter (fluctuación)", "Ancho de banda", "Rendimiento real (throughput)"], "El jitter es la variación del retardo entre paquetes, y el tráfico en tiempo real como la voz sufre cuando es alto. La latencia es el retardo en sí, que el escenario dice que es bajo en promedio.", ["La latencia es el retardo en sí; el problema aquí es que el retardo cambia de paquete a paquete.", null, "El ancho de banda es la capacidad del enlace, no qué tan uniformemente llegan los paquetes en el tiempo.", "El throughput es la tasa de datos realmente alcanzada, que no dice nada sobre la temporización desigual de los paquetes."]],
  "x2": ["Un gobierno municipal enlaza sus oficinas, bibliotecas y estaciones de bomberos repartidas por toda la ciudad en una sola red. ¿Qué tipo de red es esta?", ["CAN", "PAN", "WLAN", "MAN"], "Una red de área metropolitana (MAN) abarca una ciudad o área metropolitana. Una red de área de campus (CAN) es más pequeña y une edificios en un solo campus.", ["Una CAN cubre un solo campus como una universidad o un parque empresarial, no una ciudad entera.", "Una PAN cubre unos pocos metros alrededor de una persona, como los dispositivos Bluetooth.", "Una WLAN es una red local inalámbrica en un solo sitio, no una red que abarque una ciudad.", null]],
  "x3": ["Un juego en línea envía actualizaciones de la posición del jugador muchas veces por segundo, y una actualización tardía es inútil porque le sigue una más nueva. ¿Qué protocolo de transporte le conviene mejor?", ["UDP, porque no espera para reenviar datos perdidos", "TCP, porque garantiza que cada actualización llegue en orden", "ICMP, porque está diseñado para transportar datos de aplicación", "TCP, porque su saludo elimina todo el retardo de red"], "UDP es sin conexión y no retransmite, así que las actualizaciones nuevas siguen fluyendo sin esperar a las perdidas. La entrega confiable y ordenada de TCP es tentadora, pero sus retransmisiones añaden retardo a datos que ya están desactualizados.", [null, "La entrega garantizada en orden implica esperar retransmisiones, lo que añade retardo a datos que ya están obsoletos.", "ICMP transporta mensajes de control y error como ping, no datos de aplicación como las actualizaciones del juego.", "El saludo de TCP añade una ida y vuelta antes de que fluyan los datos; no elimina el retardo."]],
  "x4": ["Un técnico está construyendo una regla de firewall para permitir el tráfico DHCP entre los clientes y un servidor DHCP. ¿Qué puertos usa DHCP?", ["TCP 20 y 21", "UDP 161 y 162", "UDP 67 y 68", "UDP 53 y 123"], "Los servidores DHCP escuchan en UDP 67 y los clientes usan UDP 68. Los puertos FTP 20 y 21 son una confusión común pero corresponden a la transferencia de archivos, no a la asignación de direcciones.", ["TCP 20 y 21 son los puertos de datos y control de FTP, no DHCP.", "UDP 161 y 162 los usa el sondeo y las traps de SNMP, no DHCP.", null, "UDP 53 es DNS y UDP 123 es NTP; ninguno se usa para las concesiones DHCP."]],
  "x5": ["Una aplicación heredada de transferencia de archivos se conecta a su servidor en el puerto TCP 21. ¿Qué protocolo es, y cuál es su principal debilidad de seguridad?", ["SFTP, que no puede cifrar el contenido de los archivos", "TFTP, que requiere contraseñas demasiado complejas", "FTP, que envía los inicios de sesión y los datos en texto claro", "HTTPS, que depende de un cifrado débil y obsoleto"], "TCP 21 es el puerto de control de FTP, y FTP envía nombres de usuario, contraseñas y datos sin cifrar. SFTP es el reemplazo seguro pero usa SSH en el puerto 22, no el puerto 21.", ["SFTP se ejecuta sobre SSH en el puerto 22 y cifra tanto los inicios de sesión como el contenido de los archivos.", "TFTP usa UDP 69 y no tiene autenticación en absoluto, así que las contraseñas no son su problema.", null, "HTTPS usa el puerto 443 y está cifrado, así que no coincide con el puerto 21 ni con esta debilidad."]],
  "x6": ["¿Qué lista muestra las unidades de datos en orden a medida que los datos BAJAN por la pila desde una aplicación hacia el cable?", ["Datos, segmento, paquete, trama, bits", "Bits, trama, paquete, segmento, datos", "Datos, paquete, segmento, trama, bits", "Segmento, datos, trama, paquete, bits"], "Los datos de la aplicación se colocan en segmentos de transporte, luego en paquetes de la capa de red, luego en tramas de enlace de datos, y finalmente se envían como bits. Intercambiar segmento y paquete es el error más común, pero el transporte va antes que la red en el camino hacia abajo.", [null, "Este es el orden inverso, que es lo que ocurre a medida que los datos suben por la pila en el receptor.", "Los segmentos se crean en la capa de transporte antes de que la capa de red construya los paquetes, así que estos dos están intercambiados.", "Los datos de la aplicación van primero y las tramas se construyen después de los paquetes, así que este orden está mezclado."]],
  "x7": ["Un switch reenvía tráfico buscando las direcciones MAC de destino en su tabla. ¿En qué capa OSI opera principalmente?", ["Capa 1, física", "Capa 3, red", "Capa 4, transporte", "Capa 2, enlace de datos"], "Las direcciones MAC y las tramas pertenecen a la capa de enlace de datos, así que un switch estándar es un dispositivo de Capa 2. La Capa 3 es tentadora porque algunos switches pueden enrutar, pero el reenvío por tabla MAC es de Capa 2.", ["La Capa 1 maneja solo señales y cableado; no lee direcciones MAC.", "La Capa 3 reenvía paquetes usando direcciones IP, que es el trabajo de un router.", "La Capa 4 se ocupa de puertos y segmentos, no del reenvío de tramas basado en MAC.", null]],
  "x8": ["Una empresa mueve su aplicación de RR. HH. de su propio centro de datos a un proveedor de SaaS. El personal remoto solía conectarse a la VPN de la empresa para usarla. ¿Cuál es el cambio MÁS probable para ellos?", ["Ahora deben usar un cable de consola para alcanzar la app", "Pueden alcanzarla por internet sin la VPN", "Necesitan una dirección IP pública estática en cada laptop", "Solo pueden usar la app desde dentro de la LAN de la oficina"], "Una app SaaS se ejecuta en la nube del proveedor y se alcanza por internet, así que los usuarios ya no necesitan un túnel hacia el centro de datos de la empresa. La opción de solo en la oficina es lo contrario de lo que hace mover a SaaS.", ["Los cables de consola son para administrar dispositivos de red localmente, no para usar aplicaciones de negocio.", null, "Las apps SaaS se alcanzan mediante acceso normal a internet; las laptops no necesitan direcciones públicas estáticas.", "Una app SaaS la aloja el proveedor en internet, así que no se limita a la red de la oficina."]],
  "x9": ["Un desarrollador quiere subir código de aplicación personalizado y que el proveedor lo ejecute, sin administrar servidores ni parchear sistemas operativos. ¿Qué modelo de nube encaja?", ["SaaS", "IaaS", "Alojamiento en las instalaciones (on-premises)", "PaaS"], "La plataforma como servicio (PaaS) proporciona un entorno de ejecución administrado donde los clientes despliegan su propio código mientras el proveedor maneja los servidores y el SO. IaaS es tentador pero deja la administración del sistema operativo al cliente.", ["SaaS entrega una aplicación terminada para usar, así que el desarrollador no podría ejecutar su propio código personalizado.", "IaaS entrega máquinas virtuales cuyos sistemas operativos el cliente debe administrar y parchear.", "El alojamiento on-premises significa comprar y operar tus propios servidores, lo opuesto de lo que se quiere.", null]],
  "x10": ["¿Qué secuencia muestra correctamente el saludo de tres vías de TCP?", ["SYN, ACK, FIN", "SYN, SYN-ACK, ACK", "ACK, SYN, SYN-ACK", "SYN, SYN-ACK, FIN"], "El cliente envía SYN, el servidor responde con SYN-ACK, y el cliente contesta con ACK para abrir la conexión. Terminar con FIN es tentador pero FIN cierra conexiones en lugar de abrirlas.", ["FIN se usa para cerrar una conexión, no para terminar de establecer una.", null, "El cliente empieza con SYN, no con ACK, así que este orden es incorrecto.", "El tercer paso acusa recibo del SYN del servidor con ACK; enviar FIN empezaría a cerrar la conexión."]],
  "x11": ["Los administradores deben transferir archivos de forma segura a un servidor usando SFTP. ¿Qué puerto debe permitir el firewall?", ["TCP 21", "UDP 69", "TCP 22", "TCP 23"], "SFTP se ejecuta dentro de SSH, que usa el puerto TCP 22. El puerto 21 es tentador por el nombre similar, pero ese es el FTP simple.", ["TCP 21 es el puerto de control del FTP simple, que no está cifrado.", "UDP 69 lo usa TFTP, que no tiene cifrado ni autenticación.", null, "TCP 23 es Telnet, un protocolo de terminal remota sin cifrar."]],
  "x12": ["¿Qué situación es causada principalmente por alta latencia en lugar de ancho de banda limitado?", ["Un enlace satelital espera mucho tiempo antes de que empiece cada respuesta", "Una descarga grande nunca supera la velocidad máxima anunciada del plan", "Muchos usuarios comparten un enlace y cada uno recibe una porción menor", "Un trabajo de respaldo nocturno llena toda la capacidad del enlace"], "La latencia es el tiempo que tardan los datos en viajar, y los enlaces satelitales añaden un retardo largo antes de cada respuesta sin importar la velocidad del enlace. La opción del enlace compartido es tentadora, pero describe la capacidad dividida, que es ancho de banda.", [null, "Alcanzar la velocidad máxima del plan es un límite de ancho de banda, no un problema de retardo.", "Que los usuarios dividan una capacidad fija es un problema de ancho de banda, no de retardo añadido.", "Un respaldo que usa toda la capacidad disponible se trata de que el ancho de banda se agote, no de retardo."]],
  "x13": ["Un host está configurado como 172.16.4.77/27. ¿Cuál es su rango de hosts utilizables?", ["172.16.4.65 a 172.16.4.94", "172.16.4.64 a 172.16.4.95", "172.16.4.33 a 172.16.4.62", "172.16.4.65 a 172.16.4.126"], "Una /27 tiene bloques de 32 direcciones, así que .77 cae en el bloque .64 con broadcast .95, dejando .65 a .94 utilizables. Listar .64 a .95 es tentador pero incluye las direcciones de red y de broadcast.", [null, "172.16.4.64 es la dirección de red y 172.16.4.95 es la dirección de broadcast, así que ninguna es utilizable.", "Ese es el bloque /27 anterior (red .32), que no contiene .77.", "Ese rango supone una /26; un bloque /27 tiene solo 32 direcciones."]],
  "x14": ["¿Qué host está en la misma subred que 192.168.10.100/26?", ["192.168.10.130", "192.168.10.60", "192.168.10.120", "192.168.10.200"], "Una /26 divide el último octeto en bloques de 64, así que .100 está en la subred .64 a .127 junto con .120. La dirección .130 parece cercana pero está pasando el broadcast .127, así que está en la siguiente subred.", ["Una /26 que empieza en .64 termina en .127, así que .130 está en la siguiente subred.", "192.168.10.60 está en la subred .0 a .63, no en la subred .64 a .127.", null, "192.168.10.200 cae en la subred .192 a .255."]],
  "x15": ["¿Qué dirección IPv6 usa un host para probar su propia pila de red, como 127.0.0.1 en IPv4?", ["fe80::1", "::1", "ff02::1", "2001:db8::1"], "La dirección de loopback de IPv6 es ::1, el equivalente de 127.0.0.1. Una dirección enlace-local fe80 es tentadora porque también es local, pero identifica una interfaz en el enlace, no al host en sí.", ["fe80::1 es una dirección enlace-local usada en el enlace local, no la de loopback.", null, "ff02::1 es la dirección multicast de todos los nodos, no la de loopback.", "2001:db8::/32 está reservada para ejemplos de documentación, no para loopback."]],
  "x16": ["Una dirección IPv6 interna comienza con fd00. ¿Qué tipo de dirección es?", ["Enlace-local (link-local)", "Unicast global", "Multicast", "Local única (unique local)"], "Las direcciones locales únicas caen dentro de fc00::/7, y las direcciones con prefijo fd son la mitad de uso común; son para uso interno privado. La enlace-local es tentadora porque también empieza con f, pero usa fe80::/10.", ["Las direcciones enlace-local comienzan con fe80 y funcionan solo en un enlace.", "Las direcciones unicast globales provienen de 2000::/3, como las que empiezan con 2 o 3.", "Las direcciones multicast comienzan con ff, no con fd.", null]],
  "x17": ["Durante una migración, una empresa ejecuta IPv4 e IPv6 al mismo tiempo en los mismos hosts y routers. ¿Cómo se llama este enfoque?", ["SLAAC", "Doble pila (dual stack)", "Traducción de direcciones de puerto (PAT)", "Direccionamiento enlace-local"], "Doble pila significa que los dispositivos ejecutan IPv4 e IPv6 al mismo tiempo, así que puede usarse cualquiera. SLAAC está relacionado con IPv6 pero solo describe cómo se asignan las direcciones.", ["SLAAC es cómo los hosts construyen sus propias direcciones IPv6, no ejecutar ambos protocolos juntos.", null, "PAT permite que muchos hosts IPv4 privados compartan una dirección pública; no ejecuta IPv6 junto con IPv4.", "El direccionamiento enlace-local da a cada interfaz una dirección solo para su enlace local."]],
  "x18": ["¿Qué dirección IPv6 está escrita INCORRECTAMENTE?", ["2001:db8:0:0:1::5", "fe80::1", "2001:db8:a::1", "2001:db8::5::1"], "El doble dos puntos puede aparecer solo una vez en una dirección, porque usarlo dos veces hace ambiguo el número de grupos de ceros faltantes. La dirección con 0:0 escrito más un :: es tentadora, pero es válida ya que :: sigue apareciendo solo una vez.", ["Esta es válida: el doble dos puntos aparece solo una vez, representando los hextetos de ceros faltantes.", "Esta es una dirección enlace-local válida con un doble dos puntos.", "Esta es válida; los ceros a la izquierda se eliminan y :: se usa solo una vez.", null]],
  "x19": ["Una PC muestra la dirección 192.168.1.25, pero un sitio web de 'cuál es mi IP' muestra 203.0.113.40. ¿Por qué difieren?", ["El router doméstico traduce la dirección privada a su dirección pública", "La PC tiene dos tarjetas de red con direcciones distintas", "El sitio web muestra la dirección del servidor DNS en su lugar", "El ISP asignó a la PC una dirección pública automáticamente mediante APIPA"], "El router usa NAT/PAT para reemplazar la dirección de origen privada de la PC con su propia dirección pública antes de enviar el tráfico a internet. La idea de las dos tarjetas es tentadora, pero el sitio web solo ve la dirección traducida del router.", [null, "El sitio web ve la dirección de la que llega el tráfico, que es la dirección pública del router, no una segunda tarjeta.", "Los sitios de 'cuál es mi IP' reportan la dirección de origen de la solicitud, no el servidor DNS.", "APIPA da direcciones 169.254.x.x cuando DHCP falla; nunca asigna direcciones públicas."]],
  "x20": ["¿Cuál es una diferencia clave entre la fibra monomodo y la multimodo?", ["La multimodo tiene un núcleo más pequeño y alcanza más lejos", "La monomodo transporta señales eléctricas, no luz", "La monomodo tiene un núcleo más pequeño y mayor alcance", "La multimodo se usa solo para conexiones de TV por cable"], "La fibra monomodo tiene un núcleo muy pequeño y normalmente una fuente láser, así que transporta señales mucho más lejos que la multimodo. La opción invertida es tentadora pero pone al revés tanto el tamaño del núcleo como la distancia.", ["Esto invierte los hechos: la multimodo tiene el núcleo más grande y el alcance más corto.", "Ambos tipos de fibra transportan luz; ninguno usa señales eléctricas.", null, "La TV por cable comúnmente usa coaxial; la fibra multimodo se usa principalmente para enlaces de datos más cortos."]],
  "x21": ["Al colocar un plug RJ-45, un técnico destrenzó varios centímetros de cada par. El enlace ahora muestra errores. ¿Qué problema es lo más probable que esté causando?", ["Una dirección APIPA en la PC", "Un SSID duplicado en la red", "Diafonía (crosstalk) entre los pares de cables", "La VLAN incorrecta en el puerto del switch"], "Trenzar los pares cancela la interferencia entre ellos, así que destrenzar demasiado deja que las señales se filtren entre pares como diafonía. Una VLAN incorrecta es tentadora pero bloquearía el tráfico, no crearía errores en el enlace.", ["APIPA es un resultado de direccionamiento por fallo de DHCP, no una falla de cableado por pares destrenzados.", "Los SSID son nombres de redes Wi-Fi y no tienen nada que ver con las terminaciones de cobre.", null, "La asignación de VLAN es configuración y no causaría errores en la capa física."]],
  "x22": ["Dos switches antiguos que no soportan auto-MDIX deben conectarse con cable de cobre. ¿Qué cable debería usarse?", ["Cable cruzado (crossover)", "Cable directo (straight-through)", "Cable de consola rollover", "Cable coaxial RG-6"], "Conectar dispositivos iguales como dos switches necesita un cable crossover cuando los puertos no pueden autodetectar con MDIX. El directo es tentador porque el equipo moderno lo maneja, pero estos switches carecen de auto-MDIX.", [null, "El directo conecta dispositivos distintos, como una PC a un switch; los dispositivos iguales sin auto-MDIX necesitan crossover.", "Un cable rollover se usa para acceso por consola, no para enlaces de datos entre switches.", "El coaxial RG-6 se usa para TV por cable y módems y no encaja en los puertos de un switch Ethernet."]],
  "x23": ["¿Qué conector se usa típicamente para líneas telefónicas analógicas y conexiones telefónicas DSL?", ["RJ-45", "LC", "BNC", "RJ-11"], "RJ-11 es el conector pequeño usado para líneas telefónicas y DSL. RJ-45 se ve similar pero es más ancho, con ocho pines para Ethernet.", ["RJ-45 es el conector más grande de ocho pines usado en los cables Ethernet.", "LC es un conector de fibra óptica pequeño, no un conector telefónico.", "BNC es un conector coaxial de bayoneta usado para equipo de video y de red más antiguo.", null]],
  "x24": ["Una laptop nueva y un punto de acceso soportan Wi-Fi 6E. ¿Por qué podría el usuario elegir la banda de 6 GHz?", ["Mejor alcance a través de paredes que 2.4 GHz", "Más canales y menos congestión", "Soporte para todos los clientes Wi-Fi antiguos", "No necesita ningún ajuste de seguridad Wi-Fi"], "La banda de 6 GHz añade muchos canales anchos y solo los dispositivos más nuevos la usan, así que hay menos congestión. Mejor alcance es tentador, pero las frecuencias más altas viajan menos lejos que 2.4 GHz.", ["Las frecuencias más altas como 6 GHz tienen menor alcance y peor penetración en paredes que 2.4 GHz.", null, "Solo los clientes Wi-Fi 6E y más nuevos pueden usar 6 GHz, así que los dispositivos antiguos no pueden unirse.", "Las redes de 6 GHz requieren protección WPA3 o Enhanced Open; no están exentas de seguridad."]],
  "x25": ["Un usuario en una habitación lejana recibe una señal débil de 5 GHz pero una señal utilizable de 2.4 GHz del mismo router. ¿Por qué?", ["5 GHz atiende solo un dispositivo a la vez", "2.4 GHz ofrece más canales sin solapamiento que 5 GHz", "Las señales de 5 GHz son bloqueadas por los ajustes de WPA3", "2.4 GHz viaja más lejos y atraviesa mejor las paredes"], "Las frecuencias más bajas pierden menos intensidad con la distancia y los obstáculos, así que 2.4 GHz llega más lejos mientras que 5 GHz es más rápida a menor distancia. La opción de canales es tentadora pero está al revés, ya que 5 GHz tiene más canales sin solapamiento.", ["5 GHz atiende muchos dispositivos a la vez; la diferencia aquí es el alcance, no un límite de dispositivos.", "2.4 GHz tiene menos canales sin solapamiento que 5 GHz, y los canales no explican el alcance.", "Los ajustes de seguridad no cambian qué tan lejos viaja una señal de radio.", null]],
  "x26": ["La laptop de un vendedor no tiene Wi-Fi en el sitio de un cliente, pero su teléfono tiene servicio 5G. ¿Cómo puede la laptop conectarse a internet?", ["Emparejar la laptop con los audífonos Bluetooth del teléfono", "Encender el punto de acceso móvil (hotspot) del teléfono y unirse a él", "Configurar la laptop para usar una dirección APIPA", "Cambiar el servidor DNS de la laptop a 8.8.8.8"], "Un hotspot móvil comparte la conexión de datos celulares del teléfono con la laptop por Wi-Fi. Cambiar el DNS es tentador cuando fallan los nombres, pero la laptop no tiene enlace de red que usar.", ["Los audífonos son accesorios de audio y no proporcionan conexión a internet a la laptop.", null, "APIPA solo permite comunicación en el enlace local y no da acceso a internet.", "Los ajustes de DNS no ayudan cuando la laptop no tiene conexión de red en absoluto."]],
  "x27": ["Un sistema CCTV antiguo usa cable coaxial con un conector de bayoneta que se empuja y gira. ¿Qué conector es este?", ["F-type", "RJ-11", "BNC", "LC"], "Los conectores BNC se fijan al cable coaxial con una bayoneta de un cuarto de vuelta y son comunes en sistemas de video antiguos. F-type también es coaxial, pero es roscado, como el usado en los módems de cable.", ["Un conector F-type se atornilla con roscas en lugar de una bayoneta que se gira.", "RJ-11 es un plug modular pequeño para líneas telefónicas, no coaxial.", null, "LC es un conector de fibra con un diseño de empujar y enganchar."]],
  "x28": ["En una Mac, ¿qué comando de Terminal muestra las direcciones IP asignadas a cada interfaz de red?", ["ifconfig", "ipconfig /all", "show ip interface brief", "tracert"], "macOS todavía usa ifconfig para mostrar las direcciones de las interfaces. ipconfig /all es tentador por el nombre similar, pero pertenece a Windows.", [null, "ipconfig /all es el comando de Windows y no es como macOS lista las interfaces.", "Ese es un comando de Cisco IOS, ejecutado en dispositivos de red, no en una Mac.", "tracert es el comando de trazado de ruta de Windows y no lista las direcciones de las interfaces."]],
  "x29": ["Los usuarios de un almacén pierden el Wi-Fi cerca de estanterías metálicas altas, lejos del único punto de acceso, que funciona en el canal 6 de 2.4 GHz. ¿Cuál es la MEJOR solución?", ["Agregar puntos de acceso más cerca de esos usuarios", "Mover el punto de acceso al canal 3", "Cambiar la seguridad de WPA2 a WPA3", "Aumentar el tiempo de concesión DHCP en las laptops"], "La distancia y las obstrucciones metálicas debilitan la señal, así que más puntos de acceso cerca de los usuarios dan una cobertura confiable. Cambiar de canal es tentador, pero el canal 3 se solapa con sus vecinos y no arregla una señal débil.", [null, "El canal 3 se solapa con los canales 1 y 6 y no hace nada respecto a la distancia o el metal que bloquea la señal.", "El protocolo de seguridad no afecta la intensidad de la señal ni la cobertura.", "El tiempo de concesión controla la renovación de direcciones, no la cobertura de radio."]],
  "x30": ["Un nuevo punto de acceso inalámbrico se monta en un techo donde no hay toma de corriente. ¿Qué permite alimentarlo a través de su cable de red?", ["Un módulo de fibra SFP", "Un cable de consola", "Un puerto de switch con capacidad PoE", "Un ajuste de puerto troncal"], "Power over Ethernet envía energía por el mismo cable de cobre que transporta los datos, lo que conviene a puntos de acceso, teléfonos y cámaras. Un puerto troncal es tentador porque los APs a menudo necesitan varias VLANs, pero el trunking no suministra energía.", ["Los módulos SFP conectan fibra u otros medios y no entregan energía a los dispositivos.", "Los cables de consola son para configurar dispositivos, no para suministrar energía.", null, "El trunking transporta múltiples VLANs; no alimenta el dispositivo conectado."]],
  "x31": ["Un switch ha aprendido que la PC B está en el puerto 5. La PC A en el puerto 3 envía una trama a la dirección MAC de la PC B. ¿Qué hace el switch?", ["Inunda la trama por todos los puertos", "Reenvía la trama solo por el puerto 5", "Envía la trama al router primero", "Descarta la trama porque la PC B ya es conocida"], "Cuando la MAC de destino está en la tabla, el switch reenvía la trama solo por el puerto correspondiente. La inundación es tentadora pero se aplica solo a destinos desconocidos.", ["La inundación ocurre solo cuando la MAC de destino es desconocida, pero aquí está en la tabla.", null, "El tráfico entre hosts de la misma VLAN pasa directamente por el switch, no por un router.", "Un destino conocido es exactamente cuando el switch reenvía la trama, no la descarta."]],
  "x32": ["Un hub está conectado al puerto 2 del switch. El switch recibe una trama en el puerto 2 cuya MAC de destino también ha aprendido en el puerto 2. ¿Qué hace el switch?", ["La inunda por todos los puertos de la VLAN", "La reenvía de vuelta por el puerto 2", "La envía a la puerta de enlace predeterminada", "Filtra (descarta) la trama"], "Si el origen y el destino están en el mismo puerto, el switch filtra (descarta) la trama porque el destino ya la vio a través del hub. Reenviarla de vuelta por el puerto 2 es tentador, pero los switches nunca envían una trama por el puerto por el que llegó.", ["El destino es conocido, así que no hay razón para inundar la trama.", "El destino ya recibió la trama a través del hub, así que el switch no la reenvía por el mismo puerto.", "Los switches no envían tramas locales a una puerta de enlace; la puerta de enlace es un ajuste del host.", null]],
  "x33": ["Una PC envía una solicitud ARP a la dirección MAC de broadcast ffff.ffff.ffff. ¿A dónde la envía el switch?", ["Solo al puerto conectado al router", "A todos los puertos de esa VLAN excepto el que llegó", "A todos los puertos de todas las VLANs del switch", "A ningún puerto, porque los switches siempre descartan las tramas de broadcast"], "Un switch inunda las tramas de broadcast por todos los puertos de la misma VLAN excepto el de entrada. Enviarla a todas las VLANs es tentador, pero las VLANs existen precisamente para limitar los broadcasts.", ["Los broadcasts van a todos los hosts de la VLAN, no solo al puerto del router.", null, "Las VLANs son dominios de broadcast separados, así que un broadcast permanece en su propia VLAN.", "Los switches reenvían los broadcasts dentro de la VLAN; los routers son los que los detienen."]],
  "x34": ["Un puerto de switch se conecta a una sola PC de escritorio que pertenece a la VLAN de contabilidad. ¿Cómo debería configurarse el puerto?", ["Como troncal (trunk) que transporta todas las VLANs", "Como puerto de administración por consola", "Como interfaz WAN enrutada", "Como puerto de acceso en la VLAN de contabilidad"], "Un dispositivo final necesita un puerto de acceso asignado a una sola VLAN. Un troncal es tentador porque también transporta la de contabilidad, pero está pensado para enlaces que transportan varias VLANs.", ["Los troncales son para enlaces a switches, routers o APs que necesitan muchas VLANs, no una sola PC.", "Los puertos de consola son puertos de hardware dedicados a la administración del dispositivo, no un ajuste de un puerto Ethernet.", "Una interfaz WAN enrutada se conecta a otras redes, no al escritorio de un usuario final.", null]],
  "x35": ["Un router recibe un paquete para 172.16.40.5, pero su tabla de enrutamiento no tiene una ruta coincidente ni una ruta predeterminada. ¿Qué le pasa al paquete?", ["El router lo descarta", "El router lo inunda por todas las interfaces", "El router lo envía de vuelta al switch", "El router lo reenvía al servidor DNS"], "Un router reenvía solo cuando encuentra una ruta coincidente o una ruta predeterminada; de lo contrario descarta el paquete y puede enviar un mensaje ICMP de inalcanzable. La inundación es tentadora, pero eso es lo que hacen los switches con las MAC desconocidas.", [null, "Los routers no inundan paquetes; la inundación es un comportamiento de switch para direcciones MAC desconocidas.", "Devolver el paquete no lo entregaría; sin una ruta el router lo descarta.", "El DNS resuelve nombres; no participa en el reenvío de paquetes que carecen de ruta."]],
  "x36": ["El host 192.168.1.10/24 quiere alcanzar 192.168.1.200. ¿Cómo envía la trama?", ["A la dirección MAC de la puerta de enlace predeterminada, encontrada por ARP", "Al servidor DNS para obtener una ruta", "Directamente a su dirección MAC, encontrada por ARP", "Como broadcast a todos los hosts"], "Ambas direcciones comparten la red 192.168.1.0/24, así que el host usa ARP para encontrar la MAC del destino y envía directamente. Enviar a la puerta de enlace es tentador, pero eso ocurre solo para destinos remotos.", ["La puerta de enlace se usa solo para redes remotas, y 192.168.1.200 está en la misma /24.", "El DNS resuelve nombres; no proporciona rutas ni reenvía tráfico.", null, "Solo la solicitud ARP se difunde; la trama de datos va a la única MAC de destino."]],
  "x37": ["¿Por qué deberían etiquetarse ambos extremos de cada cable de parcheo y cada puerto del panel de parcheo?", ["Para aumentar el ancho de banda del cable", "Porque los cables sin etiqueta no pueden transportar PoE", "Para rastrear los enlaces rápido y evitar errores", "Para que el switch aprenda las direcciones MAC más rápido"], "Las etiquetas claras permiten a los técnicos encontrar el cable correcto rápido durante cambios y caídas, reduciendo errores. La opción del ancho de banda es tentadora solo si se confunde el etiquetado con la certificación del cable.", ["Las etiquetas no cambian el rendimiento eléctrico de un cable.", "PoE funciona sin importar si un cable está etiquetado.", null, "El aprendizaje de MAC proviene de las direcciones de origen de las tramas, no de las etiquetas físicas."]],
  "x38": ["Un ingeniero te pide conectar un servidor al puerto de switch Gi1/0/12 usando el panel de parcheo. El jack 12 del panel está etiquetado para una impresora. ¿Qué deberías hacer PRIMERO?", ["Confirmar a qué puerto de switch corresponde realmente cada jack", "Conectar el servidor al jack 12 de todos modos", "Desconectar la impresora y reutilizar su cable", "Usar cualquier puerto libre y avisarle al ingeniero después"], "Los números del panel de parcheo no siempre coinciden con los números de los puertos del switch, así que verificar el mapeo evita caídas y parcheos incorrectos. Conectar de todos modos es tentador porque los números coinciden, pero la etiqueta muestra que podrían no corresponder.", [null, "La etiqueta sugiere que el jack 12 no corresponde a Gi1/0/12, así que podrías desconectar la impresora o parchear el puerto equivocado.", "Esto causa una caída de la impresora sin confirmar el puerto correcto.", "El ingeniero planeó un puerto específico, quizás con ajustes de VLAN, así que un puerto aleatorio puede no funcionar."]],
  "x39": ["¿Qué afirmación compara correctamente un router con un switch que no tiene VLANs?", ["El switch reenvía entre subredes diferentes usando una tabla de enrutamiento", "Un router reenvía usando solo su tabla MAC", "El switch bloquea los broadcasts por defecto", "Un router separa dominios de broadcast; ese switch no"], "Cada interfaz de router es su propio dominio de broadcast, mientras que un switch sin VLANs reenvía los broadcasts a todos los puertos. Decir que el switch bloquea los broadcasts es tentador, pero los switches los inundan.", ["Un switch de Capa 2 no tiene tabla de enrutamiento y no puede enrutar entre subredes.", "Los routers toman decisiones de reenvío usando direcciones IP y tablas de enrutamiento.", "Un switch inunda los broadcasts por todos sus puertos; no los bloquea.", null]],
  "x40": ["Una trama cruza un troncal 802.1Q entre dos switches. ¿Cómo sabe el switch receptor a qué VLAN pertenece?", ["La dirección IP de destino muestra la VLAN", "Se agrega una etiqueta de VLAN a la trama Ethernet", "Cada VLAN usa un cable físico separado", "El switch verifica el nombre DNS del emisor"], "802.1Q inserta en las tramas del troncal una etiqueta con el ID de VLAN, aparte de la VLAN nativa sin etiqueta. Los cables separados son tentadores, pero el propósito de un troncal es compartir un enlace.", ["Los switches no leen direcciones IP para decidir la pertenencia a una VLAN en un troncal.", null, "Un troncal transporta muchas VLANs sobre un enlace, así que no se usan cables separados.", "Los nombres DNS no juegan ningún papel en la identificación de VLAN en la Capa 2."]],
  "x41": ["Una PC está configurada como 10.1.1.50/24 con puerta de enlace predeterminada 10.1.2.1. Puede hacer ping a hosts locales pero nada en otras redes. ¿Qué está mal?", ["No se puede alcanzar el servidor DNS", "El puerto del switch está configurado como troncal", "La máscara debería ser /16 para alcanzar hosts remotos", "La puerta de enlace no está en la propia subred de la PC"], "Una puerta de enlace predeterminada debe estar en la propia subred del host (10.1.1.0/24 aquí), así que 10.1.2.1 no puede alcanzarse y el tráfico remoto falla. Ampliar la máscara es tentador, pero solo oculta la verdadera mala configuración.", ["Un problema de DNS no detendría los pings a direcciones IP remotas.", "Si el puerto estuviera mal configurado, los pings locales probablemente también fallarían.", "Una máscara más ancha haría que la PC tratara los hosts remotos como locales, lo que no arregla el enrutamiento.", null]],
  "x42": ["En la metodología de resolución de problemas, ¿qué viene justo después de establecer una teoría de la causa probable?", ["Documentar los hallazgos y las lecciones aprendidas", "Probar la teoría para determinar la causa", "Verificar la funcionalidad completa del sistema", "Identificar el problema"], "Después de formar una teoría, la pruebas para confirmar o descartar la causa antes de planear una corrección. Verificar la funcionalidad es tentador, pero corresponde a después de implementar la corrección.", ["La documentación es el paso final, después de que la corrección se verifica.", null, "La verificación viene después de llevar a cabo la corrección, no antes de probar la teoría.", "Identificar el problema es el primer paso y ocurre antes de formar cualquier teoría."]],
  "x43": ["Un técnico quiere que Wireshark registre solo el tráfico hacia y desde el host 10.0.0.5 para que el archivo de captura se mantenga pequeño durante una captura larga. ¿Qué debería usar?", ["Un filtro de visualización aplicado después", "Guardar el archivo en formato .pcapng", "Un filtro de captura (capture filter) configurado antes de empezar", "Seguir el flujo TCP (Follow TCP stream)"], "Los filtros de captura deciden qué paquetes se registran, así que el archivo solo contiene el tráfico deseado. Un filtro de visualización es tentador porque usa una idea similar, pero solo cambia la vista.", ["Los filtros de visualización solo ocultan paquetes en pantalla; todos los paquetes aún se capturan y se guardan.", "El formato de archivo no reduce lo que se captura.", null, "Follow TCP stream muestra una conversación después de la captura; no limita el registro."]],
  "x44": ["En una PC con Linux, ¿qué comando lista cada salto de router en la ruta a un destino?", ["traceroute", "tracert", "nslookup", "ip route"], "Linux usa traceroute para mostrar cada salto hacia un destino. tracert es tentador porque hace lo mismo, pero es el nombre del comando en Windows.", [null, "tracert es la versión del comando en Windows, no la de Linux.", "nslookup consulta el DNS para la resolución de nombres y no muestra los saltos.", "ip route muestra la tabla de enrutamiento local, no los saltos a lo largo de una ruta."]],
  "x45": ["Una PC con Windows recibió una dirección incorrecta de un servidor DHCP no autorizado que ahora se ha retirado. ¿Qué comandos le conseguirán una nueva concesión del servidor real?", ["ipconfig /release, luego ipconfig /renew", "ipconfig /flushdns", "ping -t 127.0.0.1", "nslookup con la opción renew"], "Liberar y luego renovar descarta la concesión incorrecta y solicita una nueva de cualquier servidor DHCP que responda. /flushdns es tentador porque también es una opción de ipconfig, pero solo afecta la caché de DNS.", [null, "Esto limpia la caché del resolutor DNS pero no cambia la concesión de la dirección IP.", "Un ping de loopback continuo prueba la pila local y no toca la concesión DHCP.", "nslookup es una herramienta de consulta DNS y no tiene nada que ver con las concesiones DHCP."]],
  "x46": ["Un técnico conecta un cable de consola a un switch nuevo que no tiene configuración. ¿Qué más se necesita para alcanzar su línea de comandos?", ["Un navegador web apuntando a la dirección IP del switch", "Un cliente de Remote Desktop", "Un emulador de terminal como PuTTY en el puerto COM correcto", "La clave de host SSH del switch"], "El acceso por consola usa una sesión serial a través de un emulador de terminal, que funciona antes de que existan ajustes de IP. SSH es tentador para el acceso CLI, pero depende de una dirección IP que el switch aún no tiene.", ["Un switch nuevo no tiene dirección IP configurada, así que un navegador no puede alcanzarlo.", "RDP es para escritorios de Windows, no para consolas de dispositivos de red.", null, "SSH necesita conectividad IP y configuración, que un switch nuevo aún no tiene."]],
  "x47": ["Un auditor captura tráfico de red y lee la contraseña Telnet de un administrador de switch en texto plano. ¿Qué cambio corrige esto?", ["Mover Telnet a un puerto diferente", "Reemplazar Telnet con SSH para la administración remota", "Usar una contraseña más larga con Telnet", "Reemplazar Telnet con TFTP"], "SSH cifra toda la sesión de administración, incluidas las credenciales, mientras que Telnet envía todo en texto claro. Una contraseña más larga es tentadora, pero seguiría siendo legible en la captura.", ["Cambiar el puerto no cifra la sesión, así que las contraseñas siguen siendo legibles.", null, "Una contraseña más larga se sigue enviando en texto claro por Telnet.", "TFTP es un protocolo de transferencia de archivos sin cifrado ni inicio de sesión."]],
  "x48": ["show interfaces status lista un puerto de switch como notconnect. ¿Qué debería revisar primero el técnico?", ["La tabla de enrutamiento del router", "Los ajustes de DNS en el switch", "La versión de IOS en el switch", "El cable y el dispositivo del otro extremo"], "notconnect significa que el puerto no ve enlace, así que un cable faltante o defectuoso o un dispositivo apagado es la causa probable. Revisar el enrutamiento es tentador, pero el enrutamiento no puede importar hasta que el enlace físico esté activo.", ["El enrutamiento es un problema de Capa 3; notconnect significa que no se detectó enlace físico.", "El DNS no afecta si un puerto detecta un enlace físico.", "La versión de IOS normalmente no impide que un solo puerto tenga enlace.", null]],
  "x49": ["Un ingeniero quiere saber qué próximo salto usará un router para alcanzar 10.20.0.0/16. ¿Qué comando muestra esto?", ["show mac address-table", "show ip route", "show cdp neighbors", "show inventory"], "show ip route muestra la tabla de enrutamiento, incluida cada red y su próximo salto. show cdp neighbors es tentador porque muestra dispositivos adyacentes, pero no cuál se usa para un destino.", ["La tabla de direcciones MAC mapea MACs a puertos de switch, no redes a próximos saltos.", null, "CDP lista los dispositivos Cisco conectados directamente, no las rutas.", "show inventory lista las partes de hardware y los números de serie."]],
  "x50": ["El ingeniero necesita los números de serie del chasis de un switch y de sus módulos SFP instalados para una devolución de hardware. ¿Qué comando debería ejecutarse?", ["show ip interface brief", "show running-config", "show ip route", "show inventory"], "show inventory lista el chasis y los módulos instalados como los SFP, con IDs de producto y números de serie. show version está relacionado pero no se ofreció, y running-config contiene solo ajustes.", ["Esto muestra las direcciones IP y el estado de las interfaces, no los números de serie del hardware.", "La configuración en ejecución contiene ajustes, no los números de serie de los módulos.", "La tabla de enrutamiento no tiene información de hardware.", null]],
  "x51": ["¿Qué comando muestra la configuración actualmente activa en la RAM de un switch Cisco?", ["show running-config", "show startup-config", "show version", "show interfaces"], "La configuración en ejecución es la activa en la RAM. La configuración de inicio es tentadora, pero es la copia guardada en NVRAM que podría no coincidir con los ajustes actuales.", [null, "La configuración de inicio se almacena en NVRAM y se carga al arrancar; puede diferir de lo que está en ejecución.", "show version muestra software, tiempo activo y detalles de hardware, no la configuración completa.", "show interfaces muestra contadores y estado de las interfaces, no toda la configuración."]],
  "x52": ["Un técnico escribe sh ip int b en un switch Cisco y obtiene la misma salida que show ip interface brief. ¿Por qué funciona esto?", ["Un alias predeterminado configura este atajo", "Las abreviaturas funcionan solo en el modo de configuración", "IOS acepta cualquier abreviatura sin ambigüedad", "IOS ignora las letras que no puede interpretar"], "Cisco IOS acepta comandos abreviados siempre que cada abreviatura coincida con solo una palabra clave, y Tab puede completarlos. La idea del alias es tentadora, pero no se necesita ningún alias para esto.", ["Funciona por las reglas de abreviatura, no porque se haya configurado un alias.", "Las abreviaturas funcionan también en los modos EXEC, como muestra este ejemplo.", null, "IOS rechaza la entrada ambigua o inválida en lugar de ignorarla en silencio."]],
  "x53": ["Un usuario reporta que el Wi-Fi está lento cada tarde, mientras que los compañeros cercanos están bien. ¿Qué información es la MÁS útil para recopilar primero?", ["La contraseña del usuario, para que puedas iniciar sesión como él y probarlo tú mismo", "El número de contrato del ISP", "El tipo de dispositivo, su ubicación, cuándo empezó y qué cambió", "Una lista de cada switch de la empresa"], "Recopilar detalles sobre el dispositivo, el lugar, el momento y los cambios recientes ayuda a acotar la causa de un problema que afecta a un solo usuario. El contrato del ISP es tentador para la lentitud de internet, pero otros en la misma conexión están bien.", ["Los técnicos nunca deberían pedir las contraseñas de los usuarios, y no describe el problema.", "Los compañeros no están afectados, así que es poco probable que el servicio de internet sea la causa.", null, "Una lista completa de switches no describe los síntomas específicos de este usuario."]],
  "x54": ["Una nueva cámara IP se instala con la contraseña de administrador predeterminada del fabricante. ¿Cuál es el primer paso MÁS importante?", ["Cambiar la contraseña predeterminada por una fuerte y única", "Ocultar el SSID de la cámara", "Desactivar el registro de la cámara", "Dejarla, ya que la cámara está en interiores"], "Las contraseñas predeterminadas son ampliamente conocidas, así que los atacantes pueden iniciar sesión a menos que se cambien. Dejarla porque está en interiores es tentador, pero los atacantes de red no necesitan acceso físico.", [null, "Ocultar un nombre de red no protege la cuenta de administrador y se evita fácilmente.", "Desactivar los registros reduce la visibilidad y no hace nada para asegurar el acceso.", "Las credenciales predeterminadas se publican en línea y pueden usarse por la red dondequiera que esté la cámara."]],
  "x55": ["¿Qué inicio de sesión usa dos tipos de factores de autenticación DIFERENTES?", ["Una contraseña y un PIN", "Dos contraseñas diferentes", "Una pregunta de seguridad y una contraseña", "Una contraseña más un código de una aplicación autenticadora"], "Una contraseña es algo que sabes y una aplicación autenticadora en un teléfono es algo que tienes, así que esto es MFA. Una contraseña y un PIN son tentadores porque son dos pasos, pero ambos son factores de conocimiento.", ["Una contraseña y un PIN son ambos algo que sabes, así que es un solo tipo de factor.", "Dos contraseñas siguen siendo solo algo que sabes.", "Ambos son factores de conocimiento, así que esto no es verdadera autenticación multifactor.", null]],
  "x56": ["Una laptop de la empresa se usa a menudo en el Wi-Fi de hoteles y cafeterías. ¿Qué firewall la protege en esos lugares?", ["El firewall de la red de la oficina", "Un firewall basado en host en la laptop", "Un firewall con estado en el router doméstico", "El servidor DNS del ISP"], "Un firewall basado en host se ejecuta en el propio dispositivo, así que protege la laptop en cualquier red. El firewall de la oficina es tentador, pero la laptop está fuera de su alcance al viajar.", ["El firewall de la oficina solo filtra el tráfico que pasa por la red de la oficina, no por la red de un hotel.", null, "Un router doméstico protege la red del hogar, no la laptop cuando está en otro lugar.", "Un servidor DNS resuelve nombres y no filtra las conexiones hacia la laptop."]],
  "x57": ["Un corte de energía deja fuera de línea el único servidor web de una empresa durante seis horas. ¿Qué parte de la tríada CIA se ve afectada?", ["Confidencialidad", "Integridad", "No repudio", "Disponibilidad"], "La disponibilidad significa que los sistemas y datos son accesibles cuando se necesitan, y un corte la daña directamente. La integridad es tentadora ya que los cortes pueden poner en riesgo los datos, pero aquí nada fue cambiado.", ["Ningún dato fue expuesto a personas no autorizadas, así que la confidencialidad no se ve afectada.", "Ningún dato fue alterado, así que la integridad no es el problema.", "El no repudio se trata de probar quién realizó una acción, no del tiempo de actividad.", null]],
  "x58": ["Unos investigadores de seguridad publican código que aprovecha un fallo conocido en un modelo de router. ¿Cómo se llama ese código?", ["Una vulnerabilidad", "Un exploit", "Un riesgo", "Un actor de amenaza (threat actor)"], "Un exploit es el código o la técnica que aprovecha una vulnerabilidad. La vulnerabilidad es tentadora porque está muy relacionada, pero es la debilidad, no la herramienta usada contra ella.", ["La vulnerabilidad es el fallo en sí; el código que lo usa es otra cosa.", null, "El riesgo es la probabilidad y el impacto del daño, no un fragmento de código.", "Un actor de amenaza es una persona o grupo, no un código."]],
  "x59": ["Una cafetería ofrece una red Wi-Fi sin seguridad habilitada y sin contraseña. ¿Cuál es el riesgo principal para los clientes?", ["La red se limita a la banda de 2.4 GHz", "Los dispositivos de los clientes no pueden obtener una dirección IP", "El tráfico inalámbrico no está cifrado, así que otros cercanos pueden capturarlo", "El servidor DNS de la cafetería no podrá resolver nombres para los dispositivos de los clientes"], "Sin seguridad Wi-Fi, las tramas se envían por el aire sin cifrar, así que los atacantes cercanos pueden capturar el tráfico no cifrado. La opción de DNS es tentadora porque los usuarios pueden notar problemas de conexión, pero el Wi-Fi abierto no rompe la resolución de nombres.", ["Los ajustes de seguridad no tienen nada que ver con qué banda se usa.", "DHCP funciona normalmente en una red abierta.", null, "La seguridad Wi-Fi no afecta la resolución de nombres DNS."]],
  "x60": ["Alguien que dice ser un ejecutivo de viaje presiona a la mesa de ayuda para que restablezca su contraseña de inmediato. ¿Qué debería hacer el técnico?", ["Verificar primero la identidad de la persona usando el proceso aprobado", "Restablecerla de inmediato porque quien llama es un ejecutivo senior", "Enviar por correo una nueva contraseña a la dirección personal que la persona proporcione", "Leer una contraseña temporal por teléfono"], "Los ingenieros sociales usan la urgencia y la autoridad, así que la identidad debe verificarse mediante el proceso aprobado antes de cualquier restablecimiento. Enviar la contraseña por correo es tentador porque evita decirla en voz alta, pero la dirección proviene de la persona no verificada.", [null, "La urgencia y la autoridad son presiones clásicas de la ingeniería social, no prueba de identidad.", "Un atacante podría proporcionar su propia dirección de correo y recibir la contraseña.", "Esto entrega credenciales a una persona no verificada que podría ser un atacante."]]
});
